/* DAWAH X — ahmad, অধ্যায় 42 · খণ্ড 42 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][42]=[[8201,8201,"","আমি আমার ভাইয়ের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَغِمَ أَنْفُ رَغِمَ أَنْفُ رَغِمَ أَنْفُ رَجُلٍ أَدْرَكَ وَالِدَيْهِ أَحَدَهُمَا أَوْ كِلَاهُمَا عِنْدَهُ الْكِبَرُ لَمْ يُدْخِلْهُ الْجَنَّةَ ‏","","",""],[8202,8202,"","বাবা আমাদের মন রক্ষা করেছে, ভালবাসার প্রতিজ্ঞা করেছে, বাবা একজন পলাতক। যে বলেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন যেন তিনি আত্মসমর্পণ করেন বা তার বাবার আদেশ পালন করেন। আমি আপনাদের বিচার করি। স্থায়ী পানি আর তারপর সে তার কাছ থেকে পানি পেয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ الْأَوْدِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏","","",""],[8203,8203,"","আমি আমার বাবাকে বলেছিলাম যে ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি আত্মসমর্পণ করবেন বলে তার প্রতিজ্ঞা করা হবে । আর আরো একটা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ ‏ ‏يَحْسِرَ ‏ ‏الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ يَقْتَتِلُ عَلَيْهِ النَّاسُ حَتَّى يُقْتَلَ مِنْ كُلِّ عَشْرَةٍ تِسْعَةٌ وَيَبْقَى وَاحِدٌ ‏","","",""],[8204,8204,"","আমরা জানতে পারলাম যে আমরা কিভাবে গর্ভবতী হতে পারি। আমি ঈশ্বরের কাছে প্রার্থনা করছি, সে একটা খরগোশকে উদ্ধার করবে, যা হয়তো তার জয় হবে। আমি তাকে স্পর্শ করব, ঈশ্বর তার কাছে প্রার্থনা করব। আমি তাকে জিজ্ঞেস করলাম, আমি কি ভাবে গর্ভবতী হব? আমি এটা আমার কাছে একটা খরগোশের মত করে বলছি, তাকে শান্তি দিবে না, আর খাবে না, ঈশ্বর যা খেতে পারবে না তা যেন না হয়... ...এটা বলার জন্য যে আমি তিন দিনের জন্য আটকে আছি","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْنَبٍ قَدْ شَوَاهَا وَمَعَهَا ‏ ‏صِنَابُهَا ‏ ‏وَأُدُمُهَا فَوَضَعَهَا بَيْنَ يَدَيْهِ فَأَمْسَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَأْكُلْ وَأَمَرَ أَصْحَابَهُ أَنْ يَأْكُلُوا فَأَمْسَكَ الْأَعْرَابِيُّ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَمْنَعُكَ أَنْ تَأْكُلَ قَالَ إِنِّي أَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ الشَّهْرِ قَالَ ‏ ‏إِنْ كُنْتَ صَائِمًا فَصُمْ أَيَّامَ ‏ ‏الْغُرِّ ‏","","",""],[8205,8205,"","আমরা আমার বাবাকে বলেছিলাম যে সে তার বাবার সাথে বের হতে যাচ্ছে. তারা শুনতে পারবে আমার বাবা তার নাম শুনেছে. সে এটা শুরু করতে পারে না. সিনেমা আর তাদের ফ্রেম আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ أَبِي إِلَى ‏ ‏الشَّامِ ‏ ‏فَكَانَ أَهْلُ ‏ ‏الشَّامِ ‏ ‏يَمُرُّونَ ‏ ‏بِأَهْلِ الصَّوَامِعِ ‏ ‏فَيُسَلِّمُونَ عَلَيْهِمْ فَسَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبْدَءُوهُمْ بِالسَّلَامِ وَاضْطَرُّوهُمْ إِلَى أَضْيَقِهِ ‏","","",""],[8206,8206,"","আমরা আমার বাবা একজন উৎপীড়ক ছিলেন যে তার বাবার জন্য যাজক হতে বলা হয়েছিল. সে একটি রাজকীয় জন্ম থেকে এমন নিষ্ঠুর হতে হবে সে তাই আমি আপনি আনা হবে তাই আপনি আনা হবে হবে হবে হবে সে যদি তাকে ফোন করত, সে কিছু যাজক বলেছে আমি তাকে দেখলাম যে সে সফল হতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مَوْلُودٍ يُولَدُ إِلَّا عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏حَتَّى يَكُونَ أَبَوَاهُ اللَّذَانِ يُهَوِّدَانِهِ ‏ ‏وَيُنَصِّرَانِهِ كَمَا ‏ ‏تُنْتِجُونَ ‏ ‏أَنْعَامَكُمْ هَلْ تَكُونُ فِيهَا ‏ ‏جَدْعَاءُ ‏ ‏حَتَّى تَكُونُوا أَنْتُمْ ‏ ‏تَجْدَعُونَهَا ‏ ‏قَالَ رَجُلٌ وَأَيْنَ هُمْ قَالَ اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏مَا أَرَى ذَلِكَ الرَّجُلَ إِلَّا كَانَ قَدَرِيًّا ‏","","",""],[8207,8207,"","ঈশ্বরের ইচ্ছা আছে আর তিনি আত্মসমর্পণ করেছেন তাদের কাজের ভয়ে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَيَسْمَعُ ‏ ‏خَفْقَ ‏ ‏نِعَالِهِمْ إِذَا وَلَّوْا ‏","","",""],[8208,8208,"","আমি আমার বাবার সাথে কথা বলেছি আমার ভাই মুক্ত হওয়ার কথা বলে, ঈশ্বরের শান্তি আছে আর বলে তুমি আমার সাথে তিন দিন সময় কাটাও না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُسَافِرْ امْرَأَةٌ مَسِيرَةَ ثَلَاثَةِ أَيَّامٍ إِلَّا مَعَ ذِي رَحِمٍ ‏","","",""],[8209,8209,"","আমি আমার ঈশ্বর সম্পর্কে একটু ভোদাই কথা বলেছি, আমি সম্ভবত আপনার মক্কেলের সাথে আড্ডা দিচ্ছি, আর তার সাথে খবর হচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَعْتَقَ ‏ ‏شِقْصًا ‏ ‏مِنْ مَمْلُوكٍ ‏ ‏فَأَجَازَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِتْقَهُ وَغَرَّمَهُ بَقِيَّةَ ثَمَنِهِ ‏","","",""],[8210,8210,"","প্রভু তার জন্য প্রার্থনা করেছিলেন এবং বলেছিলেন যে, যে তার নিজের চোখে তার মজা খুঁজে পাবে, সে তার ইচ্ছামতোই করবে । ভেতরে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ وَجَدَ مَتَاعَهُ عِنْدَ مُفْلِسٍ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[8211,8211,"","আমরা ক্ষমা চেয়ে কথা বলেছি আর আমরা যখন কথা বলেছি, তখন আমরা আমার বাবার সবচেয়ে ভালটা ভুলে গিয়েছিলাম, যিনি আমাকে সাহায্য করতে পারতেন । এটা কর, চাঁদ একটা পুরস্কার।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ لِي ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏مَا تَقُولُ فِي الْعُمْرَى قُلْتُ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ ‏","","",""],[8212,8212,"","আমরা একজন মানুষের মৃত্যুর কথা বলেছি যে তোমার সাথে কথা বলেছে, ঈশ্বর তাকে প্রার্থনা করেছেন আর তাকে যাদের সেবা করতে বলা হয়েছে তাদের কাছে আত্মসমর্পণ করেছে। আমি তার অ্যাপার্টমেন্টে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ امْرَأَتَانِ يَمِيلُ لِإِحْدَاهُمَا عَلَى الْأُخْرَى جَاءَ يَوْمَ الْقِيَامَةِ وَأَحَدُ ‏ ‏شِقَّيْهِ ‏ ‏سَاقِطٌ ‏","","",""],[8213,8213,"","আমরা যে বধিরদের কথা বলেছি, আমরা তাদের কথা বলছি, আমি তার ইচ্ছার কথা বলছি, সে বলবে বৃষ্টি হবে নাকি দেরি করে যাবে o-oo-ooo-oo-ooo-ooo-ooo-oo-ooও-oooo-ooo-oooo-to-oooo-to-ooooooo oo o o o o oo-o oo o oooo-o o oo o-o-oooooo o oo-o o o o o o-o-oo-o o oooooooooo-to-oooo o o o o o-ooo-oo-ooo-o-o o o o-to-to-o-to-o-o o o o o-o o o o o o-o-o o o-o-o-o o-to-o-o-o-to-to-o-o-o-o-o-o-oo o-o-oo-oo-oo-ooo-ooo-oo-o-ooo-ooo-ooo-ও-oooooooo-ooo-oooo-to প্রদর্শন প্রদর্শন প্রদর্শন প্রদর্শন করা হবে ঈশ্বর, আমি এটা করবো না, আমি তোমার কাছে কিছু বলার জন্য তোমার সাথে হাত মেলাই নি, কিন্তু আমি তোমাকে নিয়ে গান গাইনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمْطِرَ ‏ ‏أَوْ تَسَاقَطَ ‏ ‏عَلَى ‏ ‏أَيُّوبَ ‏ ‏فَرَاشٌ مِنْ ذَهَبٍ فَجَعَلَ يَلْتَقِطُ فَأَوْحَى اللَّهُ إِلَيْهِ يَا ‏ ‏أَيُّوبُ ‏ ‏أَفَلَمْ أُوَسِّعْ عَلَيْكَ قَالَ بَلَى وَلَكِنِّي لَا غِنَى بِي عَنْ فَضْلِكَ ‏","","",""],[8214,8214,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছিলাম এবং যিনি সকাল থেকে যাওয়ার কথা বলেছিলেন, তিনি আমাকে জানিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى ‏ ‏يَعْنِي مِنْ الصُّبْحِ رَكْعَةً ثُمَّ طَلَعَتْ الشَّمْسُ فَلْيُصَلِّ إِلَيْهَا أُخْرَى ‏","","",""],[8215,8215,"","আমরা আমাদের সাথে যা ঘটেছে তার কথা বলছিলাম, কিন্তু আমি এ নিয়ে কথা বলতে চেষ্টা করেছি। আমি যা বলছি বা বলছি, আমি ঈশ্বরের সমবেদনা পছন্দ করি। স্পর্শ করো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ ‏ ‏أَوْ قَالَ أَحَبُّ ‏ ‏إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8216,8216,"","সে এটা করেছে কারণ সে আমাকে আকাশে মিথ্যা বলেছিল, সে মিথ্যা বলেছিল, ঘুরে দাঁড়াও।","‏ ‏قَالَ وَأَحْسَبُهُ ‏ ‏قَالَ ‏ ‏عَنْ يَمِينِ الْعَرْشِ مُنَادٍ يُنَادِي فِي السَّمَاءِ السَّابِعَةِ أَعْطِ مُنْفِقًا ‏ ‏خَلَفًا ‏ ‏وَأَعْطِ ‏ ‏أَوْ ‏ ‏عَجِّلْ ‏ ‏لِمُمْسِكٍ ‏ ‏تَلَفًا ‏","","",""],[8217,8217,"","সে বলেছিল আমার বাবা একজন পলাতক, যে তার জন্য দোয়া করে যুদ্ধের জন্য... ...আর যুদ্ধের জন্য আত্মসমর্পণ করে।","‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كَسْبِ الْحَجَّامِ ‏ ‏وَكَسْبِ الْأَمَةِ ‏","","",""],[8218,8218,"","আমি জোর দিয়ে বলছি যে, তার কাছে প্রার্থনা করা এবং ঘুম না ওঠায় তার ঘুম হবে না","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ وَاسِعٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ يُقَالُ لَهُ ‏ ‏مَعْرُوفٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏لَا أَنَامَ إِلَّا عَلَى ‏ ‏وَتْرٍ ‏","","",""],[8219,8219,"","আমরা বাবার ভালোবাসা নিয়ে কথা বলেছি আর সে টাকা বাঁচার চেষ্টা করছে, সে বলল ঈশ্বর তাকে উদ্ধার করতে বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْعَتَكِيِّ وَهُوَ يَحْيَى بْنُ مَالِكٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[8220,8220,"","ঈশ্বর তাকে আদেশ দিয়েছেন, আমি যদি তার সবচেয়ে ভাল বসি এবং হার মানতে চেষ্টা করি, তা হলে তাকে আত্মসমর্পণ করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ وَأَجْهَدَ نَفْسَهُ فَقَدْ وَجَبَ الْغُسْلُ أَنْزَلَ أَوْ لَمْ يُنْزِلْ ‏","","",""],[8221,8221,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি হয়তো তার মতো সেবা করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَدَّمُوا بَيْنَ يَدَيْ رَمَضَانَ بِصَوْمِ يَوْمٍ وَلَا يَوْمَيْنِ إِلَّا رَجُلٌ كَانَ صِيَامَهُ فَلْيَصُمْ ‏","","",""],[8222,8222,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তার কাছে প্রার্থনা করেছিলেন এবং যিনি ভাগ্যের কাছে গিয়েছিলেন এবং তার নিজের কাছে আত্মসমর্পণ করবেন। তিনি বলেছিলেন, আমরা এমন এক ছেলেকে নিয়ে এই বিল্ডিং-এ কথা বলেছি।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏","","",""],[8223,8223,"","আমরা তার মতো বাচ্চাদের নিয়ে ঈশ্বরের কাছে যাই ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ يَعْنِي الْأَحْوَلَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَوَضَّأَ قَدَمَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[8224,8224,"","আমরা আমার বাবার সাথে আমার ভালবাসার জন্য লড়াই করার চেষ্টা করেছি, সে বলবে তুমি একজন নারীর বাগদত্তা বিয়ে করবে না, যদি না সে তোমার আনুগত্যহীন হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَهْجُرُ امْرَأَةٌ فِرَاشَ زَوْجِهَا إِلَّا لَعَنَتْهَا مَلَائِكَةُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8225,8225,"","আমার বাবার কথা বলেছিলাম আমার ভাই একজন উৎপীড়ক। আমি বিশ্বাস করি এটা সন্দেহজনক নয়, তুমি আমার পরিকল্পনা নিয়ে মাথা ঘামাচ্ছো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ إِيمَانٌ لَا شَكَّ فِيهِ وَغَزْوٌ لَا ‏ ‏غُلُولَ ‏ ‏فِيهِ وَحَجٌّ ‏ ‏مَبْرُورٌ ‏ ‏وَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏وَحَجَّةٌ مَبْرُورَةٌ تُكَفِّرُ خَطَايَا تِلْكَ السَّنَةِ ‏","","",""],[8226,8226,"","বাবা আমার বাবার সাথে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে তিন বার জিজ্ঞাসাবাদ করা হয়েছে। বাবার কাছে তার ছেলে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَهُنَّ لَا شَكَّ فِيهِنَّ دَعْوَةُ الْمَظْلُومِ وَدَعْوَةُ الْمُسَافِرِ وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ ‏","","",""],[8227,8227,"","আমরা কামনার সাথে কথা বলেছি, আমরা খুশি হয়েছি, আমার বাবার ছেলে আমাকে উপহার দেওয়ার জন্য লড়াই করছে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি তার কাছে আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏عِسْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏السَّدْلِ ‏","","",""],[8228,8228,"","আমরা আবেগে বাপ্তাইজিত হয়েছি জেব্রার প্রতি আবেগ নিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَلَغَهُ مَوْتُ ‏ ‏النَّجَاشِيِّ ‏ ‏صَلَّى عَلَيْهِ وَصَفُّوا خَلْفَهُ وَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[8229,8229,"","আমরা একটি জঘন্য দেওয়াল তৈরি করেছি যে একটি আবেগের কথা আমরা বলছি যা আমাকে শুনতে বা শুনতে বাধ্য করেছে এটা গোপন না। প্রতিটি শক্তির তাপ, আমি শুনতে পাই। ঈশ্বরের সেবা কর, তোমাকে লুকানোর দরকার।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏ ‏فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَوْرِ جَهَنَّمَ فِي كُلِّ صَلَاةٍ قِرَاءَةٌ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[8230,8230,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমরা বাবার গোপন স্বপ্নের মাধ্যমে ঘটেছে। সে বলত, সকালে থেকে তোমাকে গাড়ি চালাতে আমি তোমাকে শিখাব। সূর্য, সূর্যকে জয় করার আগেই পাখি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ وَمَنْ أَدْرَكَ رَكْعَةً أَوْ رَكْعَتَيْنِ مِنْ صَلَاةِ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ ‏","","",""],[8231,8231,"","আমরা বাবার আবেগ নিয়ে কথা বলেছি, আমরা আমার ছেলের স্বপ্নের দ্বারা নিশ্চিত হয়েছি, যদি আমি ঘুম থেকে জেগে উঠি, আল্লাহ্ তাকে আত্মসমর্পণ করতে হবে। তিন গজের।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلْيُفْرِغْ عَلَى يَدَيْهِ مِنْ إِنَائِهِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[8232,8232,"","আমরা এমন এক ছেলের সাথে কথা বলেছি যে জয় করতে পেরে খুশি হবে। ঈশ্বরের দোহাই তাকে দেয়া হয়েছে আর তিনি জিজ্ঞেস করেছেন যে আমার ছেলের জন্য একজন মানুষ সুখী হবে আমি আনন্দিত যে, একজন পুরুষ যার পক্ষে সম্ভব সে সক্ষম হতে সক্ষম হতে পারে। তাকে বলা হয়েছে, সে কিভাবে তাদের খুঁজে বের করতে চাচ্ছে। সে তাকে বিষ প্রয়োগ করতে দিল। তাই সে লেকের বাইরে বের হয়ে গেল এবং তারপর সে তার হারিয়ে গেল। আর তারপর সে একটা নৌকা খুজে পেল, আর সে একটা গর্ত খুঁজে পেল, আর তারপর সে তার ভিতরে প্রবেশ করলো। আর তারপর তারা বলল, তুমি জান আমি একে অপরকে খুন করবো। \" ঈশ্বরের কাছে আমি খুশি যে, আমি খুশি।\" আমি তাকে খুঁজে বের করার চেষ্টা করছি। \"তুমি তাকে লে-তে আবার ফোন করবে যতক্ষণ না সে এটা নিয়ে পড়ে যায়। সে চলে যায়। আমি শুধু তাকে খুঁজতে চাচ্ছিলাম। আমি অনেক দূর চলে যাওয়ার আগে একটা নৌকা খুঁজে পেয়েছিলাম । এটা বলে যে, ঈশ্বর আপনাকে লুকিয়ে থাকতে দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏ذَكَرَ أَنَّ رَجُلًا مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏سَأَلَ بَعْضَ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏أَنْ يُسَلِّفَهُ أَلْفَ دِينَارٍ قَالَ ائْتِنِي بِشُهَدَاءَ أُشْهِدُهُمْ قَالَ كَفَى بِاللَّهِ شَهِيدًا قَالَ ائْتِنِي بِكَفِيلٍ قَالَ كَفَى بِاللَّهِ كَفِيلًا قَالَ صَدَقْتَ فَدَفَعَهَا إِلَيْهِ إِلَى أَجَلٍ مُسَمًّى فَخَرَجَ فِي الْبَحْرِ فَقَضَى حَاجَتَهُ ثُمَّ ‏ ‏الْتَمَسَ ‏ ‏مَرْكَبًا يَقْدَمُ عَلَيْهِ لِلْأَجَلِ الَّذِي كَانَ أَجَّلَهُ فَلَمْ يَجِدْ مَرْكَبًا فَأَخَذَ خَشَبَةً فَنَقَرَهَا وَأَدْخَلَ فِيهَا أَلْفَ دِينَارٍ وَصَحِيفَةً مَعَهَا إِلَى صَاحِبِهَا ثُمَّ ‏ ‏زَجَّجَ ‏ ‏مَوْضِعَهَا ثُمَّ أَتَى بِهَا الْبَحْرَ ثُمَّ قَالَ اللَّهُمَّ إِنَّكَ قَدْ عَلِمْتَ أَنِّي اسْتَلَفْتُ مِنْ فُلَانٍ أَلْفَ دِينَارٍ فَسَأَلَنِي كَفِيلًا فَقُلْتُ كَفَى بِاللَّهِ كَفِيلًا فَرَضِيَ بِكَ وَسَأَلَنِي شَهِيدًا فَقُلْتُ كَفَى بِاللَّهِ شَهِيدًا فَرَضِيَ بِكَ وَإِنِّي قَدْ جَهِدْتُ أَنْ أَجِدَ مَرْكَبًا أَبْعَثُ إِلَيْهِ بِالَّذِي لَهُ فَلَمْ أَجِدْ مَرْكَبًا وَإِنِّي اسْتَوْدَعْتُكَهَا فَرَمَى بِهَا فِي الْبَحْرِ حَتَّى ‏ ‏وَلَجَتْ ‏ ‏فِيهِ ثُمَّ انْصَرَفَ يَنْظُرُ وَهُوَ فِي ذَلِكَ يَطْلُبُ مَرْكَبًا يَخْرُجُ إِلَى بَلَدِهِ فَخَرَجَ الرَّجُلُ الَّذِي كَانَ أَسْلَفَهُ يَنْظُرُ لَعَلَّ مَرْكَبًا يَجِيءُ بِمَالِهِ فَإِذَا بِالْخَشَبَةِ الَّتِي فِيهَا الْمَالُ فَأَخَذَهَا لِأَهْلِهِ حَطَبًا فَلَمَّا كَسَرَهَا وَجَدَ الْمَالَ وَالصَّحِيفَةَ ثُمَّ قَدِمَ ‏ ‏الرَّجُلُ الَّذِي كَانَ تَسَلَّفَ مِنْهُ فَأَتَاهُ بِأَلْفِ دِينَارٍ وَقَالَ وَاللَّهِ مَا زِلْتُ جَاهِدًا فِي طَلَبِ مَرْكَبٍ لِآتِيَكَ بِمَالِكَ فَمَا وَجَدْتُ مَرْكَبًا قَبْلَ الَّذِي أَتَيْتُ فِيهِ قَالَ هَلْ كُنْتَ بَعَثْتَ إِلَيَّ بِشَيْءٍ قَالَ أَلَمْ أُخْبِرْكَ أَنِّي لَمْ أَجِدْ مَرْكَبًا قَبْلَ هَذَا الَّذِي جِئْتُ فِيهِ قَالَ فَإِنَّ اللَّهَ قَدْ أَدَّى عَنْكَ الَّذِي بَعَثْتَ بِهِ فِي الْخَشَبَةِ فَانْصَرِفْ بِأَلْفِكَ رَاشِدًا ‏","","",""],[8233,8233,"","আমরা বাবা আমাকে বলতে চাই যে কিভাবে ভয় পেতে হয়। বাবার কুমারী বলতে কষ্ট হয় যে তিনি তার বাবার কাছে প্রার্থনা শুনেছেন এবং বললেন তিনি কে। সেই মহান ব্যক্তি যে বলতে পারে, যিনি ছিলেন। আমি তাকে বলেছিলাম, আমি জানি না যে, আমি তাকে ভয় পাব। আমি জানি না, আমি তাকে আমি বলছি, আমি জানি না যে, আমি সত্যিই অনেক কষ্ট পেয়েছি। কিন্তু আমি জানি, আমি জানি না যে, আমি সত্যিই জানি না। আমি তাকে আমি জানি না। আমি জানি, আমি যদি আমার বাবা আমাদের কথা বলি, আমি সত্যিই অনেক কষ্ট করে, কিন্তু আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি না। সে তোমার জন্য কোন ভগবান নেই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَسْوَدِ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏شَدَّادٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَمِعَ رَجُلًا ‏ ‏يَنْشُدُ ‏ ‏فِي الْمَسْجِدِ ‏ ‏ضَالَّةً ‏ ‏فَلْيَقُلْ لَهُ لَا أَدَّاهَا اللَّهُ إِلَيْكَ فَإِنَّ الْمَسَاجِدَ لَمْ تُبْنَ لِهَذَا ‏","","",""],[8234,8234,"","আমরা ঈশ্বরের সমস্যা নিয়ে কথা বলেছি, তোমার সমস্যার জন্য আমাকে সাহায্য করতে... ...দুই ছেলে আমার বাবার সাথে হাঁটছে, যে বলেছে সে কখনো বলবে না যে সে আমাকে বলবে... বাবা একটা ঘোড়া যে মাছকে সমাধান করে ঈশ্বরের শান্তি নষ্ট করতে পারে, সে তার প্রহরীকে বিক্রির জন্য ভুল লোক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏بِمَكَّةَ ‏ ‏حَدَّثَنِي ‏ ‏الضَّحَّاكُ يَعْنِي ابْنَ عُثْمَانَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِمَرْوَانَ ‏ ‏أَحْلَلْتَ بَيْعَ الرِّبَا فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏مَا فَعَلْتُ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَحْلَلْتَ بَيْعَ الصُّكُوكِ وَقَدْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الطَّعَامِ حَتَّى ‏ ‏يَسْتَوْفِيَ ‏ ‏قَالَ ‏ ‏فَخَطَبَ النَّاسَ ‏ ‏مَرْوَانُ ‏ ‏فَنَهَى عَنْ بَيْعِهَا ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَنَظَرْتُ إِلَى حَرَسِ ‏ ‏مَرْوَانَ ‏ ‏يَأْخُذُونَهَا مِنْ أَيْدِي النَّاسِ ‏","","",""],[8235,8235,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম যে আমি একটা কুত্তার ছেলে, আমার বাবা তার ইচ্ছার সবচেয়ে ভালো ছেলে, তার ঠিক এখানে থেকে শয়তান তার টাকা খায় আর তার টাকা পান করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نُعْمَانُ يَعْنِي ابْنَ رَاشِدٍ الْجَزَرِيَّ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وَيَشْرَبْ بِيَمِينِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[8236,8236,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমি নাবিকের ছেলে। আমার বাবা আমার বাবার সাথে কথা বলেছে, তার সাথে কথা বলেছে, যেন আমি একজন দাস। আমি নারী। তার স্বামী আমাদের বাবা। আমি এখন আমার বাবার সাথে কথা বলেছি। আমি আমার বাবার সাথে কথা বলেছি, আমার বাবার সাথে কথা বলেছি, আমার বাবার সাথে, আমি একজন জাত্যবাদী। আমি এখন আমার বাবার সাথে কথা বলেছি, আমি একজন নারী। আমি এখন আমার বাবার সাথে কথা বলেছি, আমি আমার বাবার সাথে কথা বলেছি, আমি আমার বাবার সাথে। আমি এখন আমার বাবার সাথে কথা বলেছি, আমি একজন মেয়ে। আমি জানি যে কিনা আমার বাবা আমাকে এই বিষয়ে কথা বলতে চায় না। আমি আমার বাবা, আমি এখন আমি এখন আমি জানি যে, আমি আসলে আমি আসলে আমি এখন আমার বাবা, আমি একজন মেয়ে। আমি জানি না যে কিনা আমার বাবা, আমি একজন নারী। আমি একজন নারী। - জোকার।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو يَعْنِي ابْنَ الْحَارِثِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو يُونُسَ سُلَيْمُ بْنُ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا ‏ ‏حَوَّاءُ ‏ ‏لَمْ تَخُنْ أُنْثَى زَوْجَهَا الدَّهْرَ ‏","","",""],[8237,8237,"","আমরা আমাদের একটি ছেলে আছে অনেক ভাল করেছি যে কখনো কথা বলে. ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমাকে ভাল কিছু দেবেন. যদি তারা জানত সে দুইবার বলেছিল.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُفْتَحُ الْأَرْيَافُ فَيَأْتِي نَاسٌ إِلَى مَعَارِفِهِمْ فَيَذْهَبُونَ مَعَهُمْ ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ قَالَهَا مَرَّتَيْنِ ‏","","",""],[8238,8238,"","আমরা একটি ছেলে কথা বলেছি যে আমাদের সাথে ঈশ্বরের প্রেম নিয়ে কথা বলেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন এবং বিশ্বাস উপভোগ করবেন না লর্ড এবং লর্ডের oluss. আপনি বিশ্বাসঘাতকতা এবং নিরাপত্তার অভিজ্ঞতা উপভোগ করছেন.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ الْإِيمَانُ وَالْكُفْرُ فِي قَلْبِ امْرِئٍ وَلَا يَجْتَمِعُ الصِّدْقُ وَالْكَذِبُ جَمِيعًا وَلَا تَجْتَمِعُ الْخِيَانَةُ وَالْأَمَانَةُ جَمِيعًا ‏","","",""],[8239,8239,"","আমরা একটা মাসোর কথা বলেছি, যে ঈশ্বরের কথা বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমাদের অ্যাপার্টমেন্টে আগুন দেবেন না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ رَبِّهِ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ النَّارَ إِلَّا شَقِيٌّ قِيلَ وَمَنْ الشَّقِيُّ قَالَ الَّذِي لَا يَعْمَلُ بِطَاعَةٍ وَلَا يَتْرُكُ لِلَّهِ مَعْصِيَةً ‏","","",""],[8240,8240,"","আমরা একটা কুত্তার বাচ্চা সম্পর্কে বলতে চেষ্টা করেছি যে আমি কাকে ভালোবাসি সেটা জানতে চেয়েছিলাম সে একটা গোপন কথা বলেছে বাবা হারাহর বলল স্বপ্ন, আমি মনে করি এটা তিন বার ভেঙ্গে ফেলবে আর আমার এর সাথে কিছু একটা আছে।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو يَعْنِي ابْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُحِبُّ أَنَّ ‏ ‏أُحُدَكُمْ ‏ ‏هَذَا ذَهَبًا أُنْفِقُ مِنْهُ كُلَّ يَوْمٍ فَيَمُرُّ بِي ثَلَاثَةٌ وَعِنْدِي مِنْهُ شَيْءٌ إِلَّا شَيْئًا أَرْصُدُهُ لِدَيْنٍ ‏","","",""],[8241,8241,"","আমার বাবার পাপের ছেলের কথা আমরা সবাই জানি, একটা ঘোড়া আল্লাহ তার কাছে প্রার্থনা করে, আর সে আমার মায়ের সিগারে থাকে, কিন্তু সে চলে যেত। যা তুমি ছিলে","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَلَامَانُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ الْأَصْبَحِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيَكُونُ فِي أُمَّتِي دَجَّالُونَ كَذَّابُونَ يُحَدِّثُونَكُمْ بِبِدَعٍ مِنْ الْحَدِيثِ بِمَا لَمْ تَسْمَعُوا أَنْتُمْ وَلَا آبَاؤُكُمْ فَإِيَّاكُمْ وَإِيَّاهُمْ لَا يَفْتِنُونَكُمْ ‏","","",""],[8242,8242,"","আমরা আমার বাবার ব্যাপারে একটা ভালো চিন্তা করেছি, একটা ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করেছে... ...আর সে বলেছে যে সে যদি তার সাথে বিশ্বাসঘাতকতা করে তাহলে সে আমাদের টাকা দেবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ سُلَيْمُ بْنُ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَوْلَا ‏ ‏حَوَّاءُ ‏ ‏لَمْ تَخُنْ أُنْثَى زَوْجَهَا ‏","","",""],[8243,8243,"","আমরা আমার বাবাকে দেবী হিসেবে নিয়ে কথা বলেছি, তার প্রত্যেক ছেলেই আমার কাছ থেকে কখনো কখনো তার ঘড়ি পেয়ে থাকে নি, তুমি কথা বলো আর বিশ্বাস করো। আর এটা মিথ্যা কথা.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ ابْنِ ‏ ‏آدَمَ ‏ ‏أَصَابَ مِنْ الزِّنَا لَا مَحَالَةَ فَالْعَيْنُ زِنَاهَا النَّظَرُ وَالْيَدُ زِنَاهَا اللَّمْسُ وَالنَّفْسُ ‏ ‏تَهْوَى وَتُحَدِّثُ وَيُصَدِّقُ ذَلِكَ وَيُكَذِّبُهُ الْفَرْجُ ‏","","",""],[8244,8244,"","আমরা আমার বাবা দেবী হিসেবে কথা বলেছি। সূর্য থেকে সূর্যকে উদ্ধার করতে হবে। সূর্য যেতে না চাইলে সে তার বিশ্বাস নিয়ে কাজ করছে না। তার বিশ্বাসের মধ্যে ধরা হয়েছে অথবা ধরা","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ الْمَغْرِبِ فَإِذَا طَلَعَتْ الشَّمْسُ مِنْ الْمَغْرِبِ آمَنَ النَّاسُ كُلُّهُمْ وَذَلِكَ حِينَ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏}","","",""],[8245,8245,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি, যে আগে ক্ষমার বিষয়ে কথা বলেছে, আল্লাহ তার কাছে প্রার্থনা করুন এবং যদি তিনি চান তাহলে আপনি যা করতে চান, তার মূল্য নিজের হাতে ছেড়ে দেবেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اكْلَفُوا مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ خَيْرَ الْعَمَلِ أَدْوَمُهُ وَإِنْ قَلَّ ‏","","",""],[8246,8246,"","আমরা সবাই একটা ছেলের কথা বলেছি, যা আমরা শুনতে পাই, ঈশ্বর আমাদের উদ্ধার করেছেন, আমি তার আকাশের বিজয়ী হবো। আমি তোমাকে একটা ভালো নাম দেবো, কিন্তু আমি কখনোই তা করবো না। আমার ছেলে, তোমাকেও, ঈশ্বরের কাছ থেকে শ্বাস নিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ يَا ‏ ‏أُمَّ الزُّبَيْرِ عَمَّةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏اشْتَرِيَا أَنْفُسَكُمَا مِنْ اللَّهِ فَإِنِّي لَا أَمْلِكُ لَكُمَا مِنْ اللَّهِ شَيْئًا وَاسْأَلَانِي مَا شِئْتُمَا يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ ‏","","",""],[8247,8247,"","আর সে আমার বাবার কাছে ফোন করবে, একটা ঘোড়া, ঈশ্বরের কাছে প্রার্থনা করবে, তাকে উদ্ধার করতে হবে আর সে আমাকে আসতে বলেছে, আজ রাতে আমার টাকা নিয়ে সে তার তৃতীয়বার বের হল। তিনি এও বলেছিলেন যে হঠাৎ করে একজন চোর হয়ে গেলে সে একজন ভালো ব্যক্তি হয়ে ওঠে । যদি আমি তাকে তার মুখে না ঢুকাতে বলি, তাহলে তাকে ছেড়ে দাও অথবা চোর চুরি করতে আর গান গাইতে পারবে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَجُلًا مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالَ لَأَتَصَدَّقَنَّ اللَّيْلَةَ بِمَالِي فَخَرَجَ بِهِ فَوَضَعَهُ فِي يَدِ زَانِيَةٍ فَأَصْبَحَ النَّاسُ يَتَحَدَّثُونَ تُصُدِّقَ عَلَى فُلَانَةَ الزَّانِيَةِ ثُمَّ خَرَجَ بِمَالٍ فَقَالَ أَيْضًا فَوَضَعَهُ فِي يَدِ سَارِقٍ فَأَصْبَحَ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏يَتَحَدَّثُونَ تُصُدِّقَ عَلَى فُلَانٍ السَّارِقِ وَخَرَجَ بِمَالٍ أَيْضًا فَوَضَعَهُ فِي يَدِ رَجُلٍ غَنِيٍّ قَالَ لَوْ شِئْتُ لَقُلْتُ لَا يَدْرِي حَيْثُ وَضَعَهُ وَرَجَعَ الرَّجُلُ إِلَى نَفْسِهِ فَأُرِيَ فِي الْمَنَامِ أَنَّ صَدَقَتَكَ قَدْ قُبِلَتْ أَمَّا الزَّانِيَةُ فَلَعَلَّهَا تَعِفُّ عَنْ زِنَاهَا وَأَمَّا السَّارِقُ فَلَعَلَّهُ أَنْ يُغْنِيَهُ عَنْ السَّرِقَةِ وَأَمَّا الْغَنِيُّ فَلَعَلَّهُ يَعْتَبِرُ فِي مَالِهِ ‏","","",""],[8248,8248,"","আমরা সবাই ঈশ্বর সম্পর্কে কথা বলেছি আমাদের বাবার সাথে একটা কুঁড়েঘরে দেখা হয়েছে, ঈশ্বর আদেশ দিয়েছেন যে সে তার মসজিদে প্রবেশ করেছে অথবা তিনি তাকে সব কিছু শিখিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ دَخَلَ مَسْجِدَنَا هَذَا لِيَتَعَلَّمَ خَيْرًا أَوْ لِيُعَلِّمَهُ كَانَ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ وَمَنْ دَخَلَهُ لِغَيْرِ ذَلِكَ كَانَ كَالنَّاظِرِ إِلَى مَا لَيْسَ لَهُ ‏","","",""],[8249,8249,"","ঈশ্বর আমাদের সাথে কথা বলেছেন, আমি কোন পরাজিত নই যে বলে আমি যা দেখেছি তা ঈশ্বরের চেয়ে ভাল। আমি একজনকে দেখেছি তার ইচ্ছার দিকে ছুটে যেতে। তাকে রক্ষা কর এবং আত্মসমর্পণ কর, কোন দুর্যোগ নয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ سُلَيْمُ بْنُ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا رَأَيْتُ شَيْئًا أَحْسَنَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ كَأَنَّ الشَّمْسَ ‏ ‏تَجْرِي فِي جَبْهَتِهِ وَمَا رَأَيْتُ أَحَدًا أَسْرَعَ فِي مِشْيَتِهِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّمَا الْأَرْضُ تُطْوَى لَهُ إِنَّا لَنُجْهِدُ أَنْفُسَنَا وَإِنَّهُ لَغَيْرُ مُكْتَرِثٍ ‏","","",""],[8250,8250,"","সে ঈশ্বরের কাছে আছে, আর আমি এটা করার দায়িত্ব দেব, ঈশ্বরকে ভয় করবে না","‏ ‏وَعَنْهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطُوا الْعَامِلَ مِنْ عَمَلِهِ فَإِنَّ عَامِلَ اللَّهِ لَا يَخِيبُ ‏","","",""],[8251,8251,"","আর সে ঈশ্বরের কাছে প্রার্থনা করবে যেন তিনি ঈশ্বরের কাছে প্রার্থনা করেন।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏لُوطًا ‏ ‏فَإِنَّهُ قَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ ‏","","",""],[8252,8252,"","আর সে তাকে ঈশ্বরের দোহাই দিয়ে বলবে যে তাকে বলতে হবে, তাকে তোমার কাছে ক্ষমা চাইতে হবে, সে বলেছে যে, ঈশ্বরের দুটি বই তার জন্য একটা সিদ্ধান্ত নিতে হবে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيَفْرَحُ أَحَدُكُمْ أَنْ ‏ ‏يَنْقَلِبَ ‏ ‏إِلَى أَهْلِهِ بِخَلِفَتَيْنِ قَالُوا نَعَمْ قَالَ ‏ ‏فَآيَتَيْنِ ‏ ‏مِنْ كِتَابِ اللَّهِ فَيَخْرُجُ بِهِمَا إِلَى أَهْلِهِ خَيْرٌ لَهُ مِنْ خَلِفَتَيْنِ ‏","","",""],[8253,8253,"","আমি তাকে ঈশ্বরের দোহাই দিয়ে ফোন করব, সে যে বিশ্বাস করবে না, তা সে বিশ্বাস করবে না। আমি হয়ত তার কাজ নথিভুক্ত করে দিতে পারি, সে এটা করেছে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ وَلَا يَدْعُو بِهِ مِنْ قَبْلِ أَنْ يَأْتِيَهُ إِلَّا أَنْ يَكُونَ قَدْ وَثِقَ بِعَمَلِهِ فَإِنَّهُ إِنْ مَاتَ أَحَدُكُمْ انْقَطَعَ عَنْهُ عَمَلُهُ وَإِنَّهُ لَا يَزِيدُ الْمُؤْمِنَ عُمْرُهُ إِلَّا خَيْرًا ‏","","",""],[8254,8254,"","আর সে তাকে সব বই লিখতে শিখিয়েছে, যাতে সে তার দুই পুরুষকে এটা বিশ্বাস করতে পারে যে সে তাকে তার কাজের জন্য নিয়োগ দিয়েছে. এই পথটি সাজানো, ভালো শব্দের বন্ধুত্ব, সব পরিকল্পনার বন্ধুত্ব।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ نَفْسٍ كُتِبَ عَلَيْهَا ‏ ‏الصَّدَقَةُ ‏ ‏كُلَّ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ فَمِنْ ذَلِكَ أَنْ يَعْدِلَ بَيْنَ ‏ ‏الِاثْنَيْنِ ‏ ‏صَدَقَةٌ ‏ ‏وَأَنْ يُعِينَ الرَّجُلَ عَلَى دَابَّتِهِ فَيَحْمِلَهُ عَلَيْهَا ‏ ‏صَدَقَةٌ ‏ ‏وَيَرْفَعَ مَتَاعَهُ عَلَيْهَا ‏ ‏صَدَقَةٌ ‏ ‏وَيُمِيطُ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ ‏ ‏صَدَقَةٌ ‏ ‏وَالْكَلِمَةُ الطَّيِّبَةُ ‏ ‏صَدَقَةٌ ‏ ‏وَكُلُّ خُطْوَةٍ يَمْشِي إِلَى الصَّلَاةِ ‏ ‏صَدَقَةٌ ‏","","",""],[8255,8255,"","আর সে ভাববাদীকে প্রার্থনা করতে বলছে যে তার কোন নাম নেই, মা আমাকে হুমকি দিচ্ছে বা আমার রাগের আওয়াজ করছে আর আমি যা বিশ্বাস করি তা বিশ্বাস করি না পাঠিয়ে দাও।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ يَهُودِيٌّ أَوْ نَصْرَانِيٌّ ثُمَّ يَمُوتُ وَلَا يُؤْمِنُ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ ‏","","",""],[8256,8256,"","আমি আমার বাবার সাথে কথা বলেছি, আমরা ঈশ্বর সম্পর্কে কথা বলেছি, তিনি বলেছেন তিনি ভালো আছেন। ঈশ্বর আমাকে কথা দিয়েছেন যে আমি কিভাবে দোষ দেই না। আমি প্রতিজ্ঞা করছি আমি শেষ নই। আমি তাকে কথা দিচ্ছি, ঈশ্বর আমাকে যে ছেলে গ্রহণ করেছেন আমি সেই ছেলে, যে আমি ছিলাম সেই বধিরদের একজন, যে আমি জন্মি নি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏كَذَّبَنِي عَبْدِي وَلَمْ يَكُنْ لَهُ لِيُكَذِّبَنِي وَشَتَمَنِي عَبْدِي وَلَمْ يَكُنْ لَهُ شَتْمِي فَأَمَّا تَكْذِيبُهُ إِيَّايَ فَيَقُولُ لَنْ يُعِيدَنِي كَالَّذِي ‏ ‏بَدَأَنِي وَلَيْسَ آخِرُ الْخَلْقِ أَهْوَنُ عَلَيَّ أَنْ أُعِيدَهُ مِنْ أَوَّلِهِ فَقَدْ كَذَّبَنِي إِنْ قَالَهَا وَأَمَّا شَتْمُهُ إِيَّايَ فَيَقُولُ اتَّخَذَ اللَّهُ وَلَدًا أَنَا اللَّهُ أَحَدٌ ‏ ‏الصَّمَدُ ‏ ‏لَمْ أَلِدْ ‏","","",""],[8257,8257,"","ভাইর কথা জেতার চেয়ে আমরা সবাই ভাল ছিলাম, আমরা একটা ছেলের সাথে কথা বলেছি যে আমরা যা করেছি, ঈশ্বর তা দূর করতে হবে যদি আমি তোমাকে জোর করি এবং চাপ দিতে সাহস করি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اكْتَحَلَ أَحَدُكُمْ فَلْيَكْتَحِلْ ‏ ‏وِتْرًا ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيَسْتَجْمِرْ ‏ ‏وِتْرًا ‏","","",""],[8258,8258,"","আমি আমার বাবাকে ঈশ্বরের কাছে কথা বলতে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اكْتَحَلَ أَحَدُكُمْ فَلْيَكْتَحِلْ ‏ ‏وِتْرًا ‏","","",""],[8259,8259,"","আমরা আমার বাবার কথা বলেছি, যে তার সাথে কথা বলেছে, সে বলেছিল যদি তিন জন হয়, সে আর কখনো তৃতীয়টা তৈরি করতে পারতো না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ ثَلَاثَةٌ جَمِيعًا فَلَا ‏ ‏يَتَنَاجَ ‏ ‏اثْنَانِ دُونَ الثَّالِثِ ‏","","",""],[8260,8260,"","আর তিনি ঈশ্বরের কাছে প্রার্থনা করতে এবং আমার মায়ের পাগলামির শেষ পরিণতির জন্য তাঁর কাছে প্রার্থনা করতে বলেন । তাদের.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ فَقَالَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَالَ آخَرُ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ قَدْ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏","","",""],[8261,8261,"","আর তাকে কল করে ঈশ্বর তাঁর সর্বোচ্চ বিচার করেছেন ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الْقَوْمُ ‏ ‏الْأَزْدُ ‏ ‏طَيِّبَةٌ أَفْوَاهُهُمْ ‏ ‏بَرَّةٌ ‏ ‏أَيْمَانُهُمْ نَقِيَّةٌ قُلُوبُهُمْ ‏","","",""],[8262,8262,"","আমরা আমার বাবা, সে আমাকে বলেছিল, মৃত্যু আমার নয়, তোমার প্রভু তোমার পালনকর প্রভুর কাছে আছে। তিনি বললেন তুমি আমাকে হারাতে চাও না। এরপর, মৃত ব্যক্তিরা এখন, কাছের ঈশ্বরের কাছে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ يَرْفَعْهُ ‏ ‏قَالَ ‏ ‏جَاءَ مَلَكُ الْمَوْتِ إِلَى ‏ ‏مُوسَي ‏ ‏فَقَالَ أَجِبْ رَبَّكَ فَلَطَمَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَيْنَ مَلَكِ الْمَوْتِ فَفَقَأَهَا فَرَجَعَ الْمَلَكُ إِلَى اللَّهِ عَزَّ وَجَلَّ فَقَالَ إِنَّكَ بَعَثْتَنِي إِلَى عَبْدٍ لَكَ لَا يُرِيدُ الْمَوْتَ وَقَدْ فَقَأَ عَيْنِي قَالَ فَرَدَّ اللَّهُ إِلَيْهِ عَيْنَهُ وَقَالَ ارْجِعْ إِلَى عَبْدِي فَقُلْ لَهُ الْحَيَاةَ تُرِيدُ فَإِنْ كُنْتَ تُرِيدُ الْحَيَاةَ فَضَعْ يَدَكَ عَلَى مَتْنِ ثَوْرٍ فَمَا دَارَتْ يَدُكَ مِنْ شَعَرَةٍ فَإِنَّكَ تَعِيشُ لَهَا سَنَةً قَالَ ثُمَّ مَاذَا قَالَ ثُمَّ الْمَوْتُ قَالَ فَالْآنَ يَا رَبِّ مِنْ قَرِيبٍ ‏","","",""],[8263,8263,"","আমরা কথা বলেছি, আমার বাবা কিভাবে তাকে ধরে রাখতে চায়, ঈশ্বরের প্রার্থনা তাকে তার মনের কাছে সমর্পণ করবে এবং তার চিন্তাভাবনার কাছে সমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏احْتَكَرَ ‏ ‏حُكْرَةً ‏ ‏يُرِيدُ أَنْ يُغْلِيَ بِهَا عَلَى الْمُسْلِمِينَ فَهُوَ خَاطِئٌ ‏","","",""],[8264,8264,"","আমরা ঈশ্বর সম্পর্কে আমার ছেলেকে বলতে চেষ্টা করেছি, আমার ভাই হারিরির ব্যাপারে খুশি হতে পেরে আমি খুশি।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَبْعَدُ فَالْأَبْعَدُ أَفْضَلُ أَجْرًا عَنْ الْمَسْجِدِ ‏","","",""],[8265,8265,"","আমরা বেনকে সাহায্য করেছি এটা কল করা হয়েছে বা করা হয়েছে. ভুলে যাও, আমি কিছু পরোয়া করি না যদি তুমি এটাকে বাতিল করে দাও, তাহলে তাকে জিজ্ঞেস করো তাকে চেষ্টা করে সেটা ধ্বংস করে ফেলা হবে।","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَمْعَانَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُخْبِرُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبَايَعُ لِرَجُلٍ بَيْنَ الرُّكْنِ ‏ ‏وَالْمَقَامِ ‏ ‏وَلَنْ يَسْتَحِلَّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏إِلَّا أَهْلُهُ فَإِذَا اسْتَحَلُّوهُ فَلَا تَسْأَلْ عَنْ هَلَكَةِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَأْتِي ‏ ‏الْحَبَشَةُ ‏ ‏فَيُخَرِّبُونَهُ خَرَابًا لَا يَعْمُرُ بَعْدَهُ أَبَدًا وَهُمْ الَّذِينَ يَسْتَخْرِجُونَ كَنْزَهُ ‏","","",""],[8266,8266,"","আমরা হেঁটেছি, মানে আমার ছেলে, অভিশাপ, আর আমরা আমার বাবা চলে যাওয়ার ব্যাপারে কথা বলেছি। প্রভু সম্মানিত হবেন । তারা যখন বলেছিল, \"তারা অনেক বড় ছিল, তারা হ্যাম পান করত, যদি এটা আমার স্বপ্ন ছিল.\" আমি তার পড়ার মেজাজে আছি, ঈশ্বরের দ্বারা অপসারণের জন্য, হতে পারে। আমি এটা ভেবে মাতাল, যতক্ষণ না তুমি জানো যে তুমি কি বলছ আর মানুষ তাদের একজনের জন্য পান করবে... তারা বলেছিল আমরা যুদ্ধ শেষ করেছি, ঈশ্বর ইচ্ছা করেই মানুষকে হত্যা করেছেন, মানুষ তাদের মুখের মুখে মারা গেছে অথবা মারা গেছে। সব মেকারই তাকে ভগবানের কাছে আছে। একজন সার্জন যিনি যদি সফল হয়েছিলেন এবং প্রভুর শেষ আশা নিয়ে বিশ্বাস করতেন, তা হলে তিনি শান্তি স্থাপন করেছেন । ওকে যেতে দাও।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ يَعْنِي ابْنَ النُّعْمَانِ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حُرِّمَتْ الْخَمْرُ ثَلَاثَ مَرَّاتٍ قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَهُمْ يَشْرَبُونَ الْخَمْرَ وَيَأْكُلُونَ ‏ ‏الْمَيْسِرَ ‏ ‏فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُمَا فَأَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَسْأَلُونَكَ عَنْ الْخَمْرِ ‏ ‏وَالْمَيْسِرِ ‏ ‏قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِنْ نَفْعِهِمَا ‏} ‏إِلَى آخِرِ الْآيَةِ فَقَالَ النَّاسُ مَا حَرَّمَ عَلَيْنَا إِنَّمَا قَالَ ‏ { ‏فِيهِمَا إِثْمٌ كَبِيرٌ ‏} ‏وَكَانُوا يَشْرَبُونَ الْخَمْرَ حَتَّى إِذَا كَانَ يَوْمٌ مِنْ الْأَيَّامِ صَلَّى رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏أَمَّ أَصْحَابَهُ فِي الْمَغْرِبِ خَلَطَ فِي قِرَاءَتِهِ فَأَنْزَلَ اللَّهُ فِيهَا آيَةً أَغْلَظَ مِنْهَا ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ ‏} ‏وَكَانَ النَّاسُ يَشْرَبُونَ حَتَّى يَأْتِيَ أَحَدُهُمْ الصَّلَاةَ وَهُوَ مُفِيقٌ ثُمَّ أُنْزِلَتْ آيَةٌ أَغْلَظُ مِنْ ذَلِكَ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ ‏ ‏وَالْمَيْسِرُ ‏ ‏وَالْأَنْصَابُ ‏ ‏وَالْأَزْلَامُ ‏ ‏رِجْسٌ ‏ ‏مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ ‏} ‏فَقَالُوا انْتَهَيْنَا رَبَّنَا فَقَالَ النَّاسُ يَا رَسُولَ اللَّهِ نَاسٌ قُتِلُوا فِي سَبِيلِ اللَّهِ ‏ ‏أَوْ مَاتُوا عَلَى فُرُشِهِمْ كَانُوا يَشْرَبُونَ الْخَمْرَ وَيَأْكُلُونَ ‏ ‏الْمَيْسِرَ ‏ ‏وَقَدْ جَعَلَهُ اللَّهُ ‏ ‏رِجْسًا ‏ ‏وَمِنْ عَمَلِ الشَّيْطَانِ فَأَنْزَلَ اللَّهُ ‏ { ‏لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ ‏ ‏جُنَاحٌ ‏ ‏فِيمَا ‏ ‏طَعِمُوا ‏ ‏إِذَا مَا اتَّقَوْا وَآمَنُوا ‏} ‏إِلَى آخِرِ الْآيَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ حُرِّمَتْ عَلَيْهِمْ لَتَرَكُوهَا كَمَا تَرَكْتُمْ ‏","","",""],[8267,8267,"","আমরা সবাই একটা ছেলের কথা বলেছি, যেমন, ঈশ্বরের একটি ভালো ঈশ্বর আছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে তার কাছে আত্মসমর্পণ করতে হবে, যে তুমি তাকে এমন কিছু করতে শিখিয়েছ যা তিনি করেননি সে এমন কিছু করেছে যা সে কখনো খেতে দেয়নি... ...তততত পর্যন্ত সে তার কাছ থেকে আশা করত না যতক্ষণ না ধরা পড়ে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ رَمَضَانَ وَعَلَيْهِ مِنْ رَمَضَانَ شَيْءٌ لَمْ يَقْضِهِ لَمْ يُتَقَبَّلْ مِنْهُ وَمَنْ صَامَ تَطَوُّعًا وَعَلَيْهِ مِنْ رَمَضَانَ شَيْءٌ لَمْ يَقْضِهِ فَإِنَّهُ لَا يُتَقَبَّلُ مِنْهُ حَتَّى يَصُومَهُ ‏","","",""],[8268,8268,"","আমরা একটি ছেলের কথা বলেছি কিন্তু কখনো বলিনি। আমার বাবা একজন দেবতা যে আমাকে তার কাছে আত্মসমর্পণ করতে হবে এবং আমি বলতে হবে যে, আপনাকে ব্যাখ্যা করতে হবে। আমি তার টেনিসে আছি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى ‏ ‏خَيَاشِيمِهِ ‏","","",""],[8269,8269,"","আমি আমার ভাইয়ের সাথে কথা বলেছি, সে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল, যদি প্রার্থনা করা হয়, তাহলে তাকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ الْقِتْبَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمٍ الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الَّتِي أُقِيمَتْ ‏","","",""],[8270,8270,"","আমরা পরিচিত হয়ে কথা বলেছি এবং বলেছিলাম যে আল্লাহ্‌র কথা শুনে, আমরা হার্ব থেকে শুনেছি। তারা কিছু করেছে তাকে উৎসাহ দেওয়ার জন্য যে তিনি তার সবচেয়ে ভালো কিছুর মধ্যে একটা করেছেন। সে তার বিখ্যাত বাবার সাথে কথা বলেছে আমরা ঈশ্বরের অনুগ্রহের কথা শুনেছি। আমার ফোন যখন তুমি বলেছিলে যে ঈশ্বর তার কাছে প্রার্থনা করেছেন, তখন তুমি তাকে প্রার্থনা করো, যে তার কাছে আত্মসমর্পণ করেছে তাই সে সবসময় বলেছে সে বলেছে যে সে কখনো এটা বলেনি।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏و قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏بُكَيْرَ بْنَ الْأَشَجِّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَلِيَّ بْنَ خَالِدٍ الدُّؤَلِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏النَّضْرَ بْنَ سُفْيَانَ الدُّؤَلِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَلَعَاتِ ‏ ‏الْيَمَنِ ‏ ‏فَقَامَ ‏ ‏بِلَالٌ ‏ ‏يُنَادِي فَلَمَّا سَكَتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ مِثْلَ مَا قَالَ هَذَا يَقِينًا دَخَلَ الْجَنَّةَ ‏","","",""],[8271,8271,"","বাবার কাছে সাহায্য করার জন্য আমরা ঈশ্বরের সাথে কথা বলেছি, হয়তো আমার বাবার জন্য সবচেয়ে ভালো দুজন মানুষ, যে তার জন্য প্রার্থনা করবে। লর্ডের দয়ায় কে আসবে... ...সে তার আদেশ অনুযায়ী প্রভুর অনুগ্রহে প্রার্থনা করবে।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مُنْتَظِرُ الصَّلَاةِ مِنْ بَعْدِ الصَّلَاةِ كَفَارِسٍ اشْتَدَّ بِهِ فَرَسُهُ فِي سَبِيلِ اللَّهِ عَلَى ‏ ‏كَشْحِهِ ‏ ‏تُصَلِّي عَلَيْهِ مَلَائِكَةُ اللَّهِ مَا لَمْ يُحْدِثْ أَوْ يَقُومُ وَهُوَ فِي ‏ ‏الرِّبَاطِ ‏ ‏الْأَكْبَرِ ‏","","",""],[8272,8272,"","আমরা ঈশ্বরের ছেলেদের কথা বলেছিলাম সকালে জোর করে চাপের মধ্যে থেকে দুই মাস সময় পার হয়ে গেছে। আমার বাবার জন্য এটা একটা উপহার যা আমার জ্ঞান নিয়ে এসেছে তা হলো ঈশ্বরের ইচ্ছা আর তাঁর ইচ্ছা। আমরা জল খুঁজে বের করি এবং জিন এবং প্রাণকে তা খুঁজে বের করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْمُثَنَّى بْنِ الصَّبَّاحِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏إِنَّا نَكُونُ بِهَذَا الرَّمْلِ فَلَا نَجِدُ الْمَاءَ وَيَكُونُ فِينَا الْحَائِضُ وَالْجُنُبُ وَالنُّفَسَاءُ فَيَأْتِي عَلَيْهَا أَرْبَعَةُ أَشْهُرٍ لَا تَجِدُ الْمَاءَ قَالَ عَلَيْكَ بِالتُّرَابِ ‏ ‏يَعْنِي التَّيَمُّمَ ‏","","",""],[8273,8273,"","আমরা বাবার মাস্টারের সাথে আমার ভালোবাসা নিয়ে কথা বলেছি। লর্ড লর্ড তার জ্ঞানের জন্য প্রার্থনা করেছেন, যেন তারা ইচ্ছার প্রতি বিশ্বস্ত থাকে। ষাঁড়, যেখানে আকাশ ছিল, এবং তাদের দ্বারা কি করা হত.","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ الرَّاسِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ أَبِي عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ لِلْأُمَرَاءِ وَيْلٌ لِلْعُرَفَاءِ وَيْلٌ لِلْأُمَنَاءِ لَيَتَمَنَّيَنَّ أَقْوَامٌ يَوْمَ الْقِيَامَةِ أَنَّ ‏ ‏ذَوَائِبَهُمْ ‏ ‏كَانَتْ مُعَلَّقَةً ‏ ‏بِالثُّرَيَّا ‏ ‏يَتَذَبْذَبُونَ بَيْنَ السَّمَاءِ وَالْأَرْضِ وَلَمْ يَكُونُوا عَمِلُوا عَلَى شَيْءٍ ‏","","",""],[8274,8274,"","আমি আমার বাবার জন্য যুদ্ধ করার চেষ্টা করার বিষয়ে কথা বলেছিলাম । হাত উপরে, আর সে তাকে যেতে দিবে না, যদি আমার আত্মা মারা যায় তাহলে আমার শক্তি কখনো মারা যেত না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بِتَمَرَاتٍ فَقُلْتُ ادْعُ اللَّهَ لِي فِيهِنَّ بِالْبَرَكَةِ قَالَ ‏ ‏فَصَفَّهُنَّ بَيْنَ يَدَيْهِ قَالَ ثُمَّ دَعَا فَقَالَ لِي اجْعَلْهُنَّ فِي ‏ ‏مِزْوَدٍ ‏ ‏وَأَدْخِلْ يَدَكَ وَلَا ‏ ‏تَنْثُرْهُ ‏ ‏قَالَ ‏ ‏فَحَمَلْتُ مِنْهُ كَذَا وَكَذَا وَسْقًا فِي سَبِيلِ اللَّهِ وَنَأْكُلُ وَنُطْعِمُ وَكَانَ لَا يُفَارِقُ ‏ ‏حَقْوِي ‏ ‏فَلَمَّا قُتِلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏انْقَطَعَ عَنْ ‏ ‏حَقْوِي ‏ ‏فَسَقَطَ ‏","","",""],[8275,8275,"","আমরা দু'টি ভাল বিচার করেছি, আমার বাবা জয়ের চেষ্টা করেছেন। বাবার অনুগ্রহের থেকে তার কাছে প্রার্থনা করার চেয়ে বরং তার জন্য প্রার্থনা করা ভালো।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى أَبُو عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ الْمَاجِشُونِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ تَلْبِيَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ إِلَهَ الْحَقِّ ‏","","",""],[8276,8276,"","আমরা দুজন নাতির কথা বলেছি যারা আমার ভালবাসার কথা বলেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন, এমনকি যারা আপনাদের মিথ্যা বলে তাদের সবাইকে বিশ্বাস করতে দেয় না। সে ছিল আমার বন্ধু। সে ছিল আমার প্রিয় দুই নাতি, সে ছিল আমার প্রিয়। আমি তাকে বলেছিলাম, সে আমার প্রিয়তম সন্তান। আমি আমার কাছে প্রার্থনা করেছি। আমি তাকে বলেছি, সে তার কাছে প্রার্থনা করলাম। আমি আমার কাছে প্রার্থনা করছি। আমি মনে করি, আমি তাকে বলেছি, আমি আমার কাছে ক্ষমা চাই।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ أَبُو عُمَرَ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ أُذَيْنٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ الْعَبْدُ الْإِيمَانَ كُلَّهُ حَتَّى يَتْرُكَ الْكَذِبَ فِي الْمُزَاحَةِ وَيَتْرُكَ ‏ ‏الْمِرَاءَ ‏ ‏وَإِنْ كَانَ صَادِقًا ‏","","",""],[8277,8277,"","আমরা দুজন দাদা-দাদীকে কথা বলেছি, যারা আমার কাছে নিজের কাছে কথা বলেছে, ঈশ্বর আমার কাছে নিজের ঋণের কথা বলেছেন। লর্ড তার জন্য প্রার্থনা করেছেন এবং যদি তিনি তাকে এই কথা বলতে বাধা দেন, তাহলে তিনি আত্মসমর্পণ করেছেন। ঈশ্বর যদি বলেন, তিনি আপনাকে আশীর্বাদ করবেন, তাহলে তিনি আপনাকে হুমকি দেবেন এবং আপনাকে প্রার্থনা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ أَبُو عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ الْحَمْدُ لِلَّهِ فَإِذَا قَالَ الْحَمْدُ لِلَّهِ قَالَ لَهُ أَخُوهُ يَرْحَمُكَ اللَّهُ فَإِذَا قِيلَ لَهُ يَرْحَمُكَ اللَّهُ فَلْيَقُلْ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[8278,8278,"","ঈশ্বর এসে ছাদের মুখ থেকে পান করা শেষ করে দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الشُّرْبِ مِنْ فَمِ ‏ ‏السِّقَاءِ ‏","","",""],[8279,8279,"","তিনি বলেন, আপনি একজন ভালো বাবাকে চলে যেতে বলেন এবং তাকে দেখতে যান । বাবা, আমরা পরের জনের নাম শুনেছি। শেষবার যখন আমি বাবাকে হারাহরকে উদ্ধার করলাম, সে বলবে আমি তাদের একজনকে বিক্রি করে দেবো। আবেগ আছে, আর তাদের কিছু একটা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ فَرُّوخَ الْجُرَيْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏يَقُولُ ‏ ‏تَضَيَّفْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَبْعًا فَكَانَ هُوَ وَامْرَأَتُهُ وَخَادِمُهُ يَعْتَقِبُونَ اللَّيْلَ أَثْلَاثًا ‏ ‏يُصَلِّي هَذَا ثُمَّ يُوقِظُ هَذَا وَيُصَلِّي هَذَا ثُمَّ يَرْقُدُ وَيُوقِظُ هَذَا قَالَ قُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَيْفَ تَصُومُ قَالَ ‏ ‏أَمَّا أَنَا فَأَصُومُ مِنْ أَوَّلِ الشَّهْرِ ثَلَاثًا فَإِنْ حَدَثَ لِي حَادِثٌ كَانَ آخِرُ شَهْرِي ‏ ‏قَالَ وَسَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بَيْنَ أَصْحَابِهِ تَمْرًا فَأَصَابَنِي سَبْعُ تَمَرَاتٍ إِحْدَاهُنَّ ‏ ‏حَشَفَةٌ ‏ ‏وَمَا فِيهِنَّ شَيْءٌ أَعْجَبُ إِلَيَّ مِنْهَا أَنَّهَا شَدَّتْ ‏ ‏مَضَاغِي ‏","","",""],[8280,8280,"","আমার বাবা একজন দেবতা ছিলেন বা তিনি ঈশ্বরের কাছে বাপ্তিস্মের বিষয়ে কথা বলেছিলেন । ব্যর্থ.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏امْرَأَةً سَوْدَاءَ ‏ ‏أَوْ رَجُلًا ‏ ‏كَانَ ‏ ‏يَقُمُّ ‏ ‏الْمَسْجِدَ فَفَقْدَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ عَنْهُ فَقَالُوا مَاتَ فَقَالَ أَلَا كُنْتُمْ ‏ ‏آذَنْتُمُونِي ‏ ‏بِهِ قَالُوا إِنَّهُ كَانَ لَيْلًا قَالَ فَقَالَ ‏ ‏دُلُّونِي عَلَى قَبْرِهِ فَدَلُّوهُ فَأَتَى قَبْرَهُ فَصَلَّى عَلَيْهِ ‏","","",""],[8281,8281,"","আমরা বাবার সাথে কথা বলেছিলাম আমার বাবার একজন জিনিয়াস হওয়ার কথা। ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং আগামীকাল সে ঈশ্বরের কাছে আমাদের গৃহ সমর্পণ করবে যেন আমি আমার ছেলের প্রতি এত নিষ্ঠুর হয়ে যাই। তুমি.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلُنَا غَدًا إِنْ شَاءَ اللَّهُ ‏ ‏بِخَيْفِ ‏ ‏بَنِي كِنَانَةَ ‏ ‏حَيْثُ تَقَاسَمُوا عَلَى الْكُفْرِ ‏","","",""],[8282,8282,"","বাবার জীবন হারানোর কথা বলেছিলাম, আমার বাবা আর কখনো তাকে ঈশ্বরের কাছে প্রার্থনা করেননি, আর সে বলবে আমি উত্তর দেব না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏جَاءَتْ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏تَطْلُبُ مِيرَاثَهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَا لَهَا سَمِعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَا أُوَرَّثُ ‏","","",""],[8283,8283,"","আমরা আমার বাবাকে একজন উৎপীড়ক হিসেবে নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আগুনে তার কথা শুনবেন না, তাই তাকে আক্রান্ত করা হবে আর তারপর সে আবার জন্ম হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعُ فِي النَّارِ اجْتِمَاعًا يَضُرُّ مُؤْمِنٌ قَتَلَ كَافِرًا ثُمَّ ‏ ‏سَدَّدَ ‏ ‏بَعْدَهُ ‏","","",""],[8284,8284,"","আমরা সবাই আমার ছেলেকে একটা প্রেম উপহার দেবার ব্যাপারে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তাকে তার কাছে সমর্পণ করবেন যাকে তিনি বিজ্ঞানের কাছে প্রতিজ্ঞা করেছেন যে তিনি ঈশ্বরের কাছে শপথ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ ‏ ‏أَلْجَمَهُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ ‏ ‏بِلِجَامٍ ‏ ‏مِنْ نَارٍ ‏","","",""],[8285,8285,"","আমরা সব বদলে গেছি, আমি আমার জন্য একটা বাপ্তিস্ম নিয়েছি, অতিথি হিসেবে নাকি তার জন্য প্রার্থনা করেছি। সে তার মুখের আংটির ভেতর বসে ছিল। কিভাবে একজন মানুষ যে কিনা আছে? সতর্ক থাকুন, বল, মাই লর্ড, আমার লজ্জা হচ্ছে তোমার গান থেকে দূরে সরে যাও, তার শরীর নিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الَّذِي يَجْلِسُ فَيَسْمَعُ الْحِكْمَةَ ثُمَّ لَا يُحَدِّثُ عَنْ صَاحِبِهِ إِلَّا بِشَرِّ مَا سَمِعَ كَمَثَلِ رَجُلٍ أَتَى رَاعِيًا فَقَالَ يَا رَاعِيَ اجْزُرْ لِي شَاةً مِنْ غَنَمِكَ قَالَ اذْهَبْ فَخُذْ بِأُذُنِ خَيْرِهَا فَذَهَبَ فَأَخَذَ بِأُذُنِ كَلْبِ الْغَنَمِ ‏","","",""],[8286,8286,"","আমার বাবার জন্য প্রার্থনা করার জন্য আমার একটা ঝুঁকি আছে আমরা সপ্তম আকাশ শেষ করার পর আমি দেখলাম যে, ছেড়ে যাওয়া হচ্ছে এবং আমরা আবার ফিরে যাব । আমি বলতে চাচ্ছি, আকাশ রাজ্য আর জ্ঞানের কথা কখনো চিন্তা করিনি তোমার সাহস।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الصَّلْتِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ لَيْلَةَ أُسْرِيَ بِي لَمَّا انْتَهَيْنَا إِلَى السَّمَاءِ السَّابِعَةِ فَنَظَرْتُ فَوْقَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَوْقِي ‏ ‏فَإِذَا أَنَا بِرَعْدٍ وَبَرْقٍ وَصَوَاعِقَ قَالَ فَأَتَيْتُ عَلَى قَوْمٍ بُطُونُهُمْ كَالْبُيُوتِ فِيهَا الْحَيَّاتُ تُرَى مِنْ خَارِجِ بُطُونِهِمْ قُلْتُ مَنْ هَؤُلَاءِ يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَؤُلَاءِ أَكَلَةُ الرِّبَا فَلَمَّا نَزَلْتُ إِلَى السَّمَاءِ الدُّنْيَا نَظَرْتُ أَسْفَلَ مِنِّي فَإِذَا أَنَا ‏ ‏بِرَهْجٍ ‏ ‏وَدُخَانٍ وَأَصْوَاتٍ فَقُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذِهِ الشَّيَاطِينُ يَحُومُونَ عَلَى أَعْيُنِ بَنِي ‏ ‏آدَمَ ‏ ‏أَنْ لَا يَتَفَكَّرُوا فِي مَلَكُوتِ السَّمَوَاتِ وَالْأَرْضِ وَلَوْلَا ذَلِكَ لَرَأَوْا الْعَجَائِبَ ‏","","",""],[8287,8287,"","আমরা একটি মহান পিতা সম্পর্কে কথা বলেছি একটি আশা হিসেবে আশা করি যে, আমরা একটি স্বপ্নের স্বপ্ন করেছি আমার বাবার কাছে একটি উপহার যে ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আমাদের ছেলেকে রক্ষা করেছেন নিরাপদ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنَا ‏ ‏الْعَاصِ ‏ ‏مُؤْمِنَانِ ‏ ‏يَعْنِي ‏ ‏هِشَامٌ ‏ ‏وَعَمْرٌو ‏","","",""],[8288,8288,"","ঈশ্বরের উত্তর তার এবং আমাদের ছেলে সারসকে তার কাছে পেশ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَا ‏ ‏الْعَاصِ ‏ ‏مُؤْمِنَانِ ‏","","",""],[8289,8289,"","আমরা সবাই আমার বাবার বাপ্তিস্মের কথা বলেছি একটি ছেলে জয় করতে গিয়ে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ঈশ্বরের কাছে বলবে যে, আমি তার সবচেয়ে ভালো আত্মার অধিকারী হব। আমি অবশ্যই করবো, নাহলে আমি এটা করবো।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ ‏","","",""],[8290,8290,"","আমি আমার বাবাকে একটা উৎপীড়ক হিসেবে বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে ভালো মানুষের দুঃখ আর প্রভুর বিখ্যাত তরবারির ভালো হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّ صُفُوفِ الرِّجَالِ الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّ صُفُوفِ النِّسَاءِ الْمُقَدَّمُ ‏","","",""],[8291,8291,"","আমরা বেনের রাজধানী সম্পর্কে একটা বাপ্তিস্মের চেয়ে অনেক ভালো করেছি, আমার ভালবাসার জন্য সে তার জন্য প্রার্থনা করেছে এবং তিন দিন ধরে অতিথিদেরও পৌঁছে দিয়েছে, তাই তুমি বলেছিলে তুমি কি বলছ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا سِوَى ذَلِكَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[8292,8292,"","আমরা সবাই আমার ভালবাসার জন্য ঈশ্বরের স্বপ্নের কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আমার বাবা মোসিকে দিতে পারেন দুস্কৃত দুদুদ দিতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ أُعْطِيَ ‏ ‏أَبُو مُوسَى ‏ ‏مَزَامِيرَ ‏ ‏دَاوُدَ ‏","","",""],[8293,8293,"","বেন মুসার কথা বলছি, আর তারা আমাকে স্বপ্নের কথা বলেছে। সে ঈশ্বরের কাছে প্রার্থনা করলো, আর সে তার আত্মার প্রাণ দেবে। সূর্য, তারা বলে, প্রভু, তাদের কামনার কারণে বিক্ষিপ্ত.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ ثَلَاثَةُ أَصْنَافٍ صِنْفٌ مُشَاةٌ وَصِنْفٌ رُكْبَانٌ وَصِنْفٌ عَلَى وُجُوهِهِمْ فَقَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَمْشُونَ عَلَى وُجُوهِهِمْ قَالَ إِنَّ الَّذِي أَمْشَاهُمْ عَلَى أَرْجُلِهِمْ قَادِرٌ عَلَى أَنْ يُمْشِيَهُمْ عَلَى وُجُوهِهِمْ أَمَا إِنَّهُمْ يَتَّقُونَ بِوُجُوهِهِمْ كُلَّ ‏ ‏حَدَبٍ ‏ ‏وَشَوْكٍ ‏","","",""],[8294,8294,"","আমরা সবাই বেনের অনুগ্রহে বাপ্তাইজিত হয়েছি, ঈশ্বরের কাছে প্রার্থনা করেছি, আর তিনি যা করেছেন তার জন্য তাকে ঈশ্বরের কাছে আত্মসমর্পণ করা হয়েছে. তার কথা শুনুন, আল্লাহ, তার দিকে তাকান, কিন্তু অন্য কেউ হয়তো তাকে মারতে ব্যর্থ হয়েছে। তারপর সেখানে গিয়ে সেখানে গিয়ে সে চলে যাবে, তার কথা শুনলে, হে ঈশ্বর, আপনার সমবেদনা প্রকাশ করে হতাশ হয়েছেন যে, আর কেউ ভিতরে নেই।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا خَلَقَ اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏اذْهَبْ فَانْظُرْ إِلَيْهَا فَذَهَبَ فَنَظَرَ فَقَالَ يَا رَبِّ وَعِزَّتِكَ لَا يَسْمَعُ بِهَا أَحَدٌ إِلَّا دَخَلَهَا ثُمَّ حَفَّهَا بِالْمَكَارِهِ ثُمَّ قَالَ اذْهَبْ فَانْظُرْ إِلَيْهَا فَذَهَبَ فَنَظَرَ فَقَالَ يَا رَبِّ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَدْخُلَهَا أَحَدٌ فَلَمَّا خَلَقَ النَّارَ قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏اذْهَبْ فَانْظُرْ إِلَيْهَا فَذَهَبَ فَنَظَرَ إِلَيْهَا فَقَالَ يَا رَبِّ وَعِزَّتِكَ لَا يَسْمَعُ بِهَا أَحَدٌ فَيَدْخُلُهَا فَحَفَّهَا بِالشَّهَوَاتِ ثُمَّ قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏اذْهَبْ فَانْظُرْ إِلَيْهَا فَذَهَبَ فَنَظَرَ إِلَيْهَا فَقَالَ يَا رَبِّ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَبْقَى أَحَدٌ إِلَّا دَخَلَهَا ‏","","",""],[8295,8295,"","আমরা সবাই আমার ভাইকে ভগবানের সাথে দেখা করে কথা বলেছি, সে বলছে তুমি তার ছেলেকে ছেড়ে দিবে... ...আর তোমার বাবা আমাদের ছুঁয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا أَصْبَحَ ‏ ‏اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ ‏ ‏نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ ‏","","",""],[8296,8296,"","আমরা হামাদ বেনের স্বপ্নের কথা বলেছি যে আমার ভালবাসার জন্য বেনকে দোষারোপ করা হচ্ছে, ঈশ্বর আমার ছেলের মালিককে উদ্ধার এবং রক্ষা করতে হবে এবং আমাকে অকারণে যেতে হবে। ঈশ্বর আত্মসমর্পণ করতে হবে, সে তার নেতাদের বলবে যে সে কে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحُمَيْدٍ ‏ ‏وَثَابِتٍ الْبُنَانِيِّ ‏ ‏وَصَالِحِ بْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ ‏ ‏مَنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي وَمَنْ ذَكَرَنِي فِي مَلَإٍ مِنْ النَّاسِ ذَكَرْتُهُ فِي مَلَإٍ أَكْثَرَ مِنْهُمْ وَأَطْيَبَ ‏","","",""],[8297,8297,"","আমরা সব বদলেছি, আমরা একটা বাপ্তিস্ম দিয়েছি এই বলে যে, সে তার সময় থেকে বেঁচে গেছে। আমার বাবা আমার বাবাকে প্রার্থনা করতে সাহায্য করবে যেন সে তার কোলে ফিরে আসে। আল্লাহ বলে নি, দুর্দশার জন্য ঈশ্বর প্রিয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سَوْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الْمُسْلِمُ أَخَاهُ أَوْ زَارَهُ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي اللَّهِ عَزَّ وَجَلَّ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ طِبْتَ وَطَابَ مَمْشَاكَ ‏ ‏وَتَبَوَّأْتَ ‏ ‏مَنْزِلًا فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مِنْ الْجَنَّةِ مَنْزِلًا ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي اللَّهِ ‏ ‏وَلَمْ يَقُلْهُ ‏ ‏عَفَّانُ ‏","","",""],[8298,8298,"","আমরা সবাই আমার ছেলের জীবন নিয়ে কথা বলেছি, সে ভগবানের কাছে অনুরোধ করেছে আর সে আত্মসমর্পণ করবে যদি তুমি তোমার দিন হারিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَبِسْتُمْ وَإِذَا تَوَضَّأْتُمْ فَابْدَءُوا بِأَيَامِنِكُمْ ‏ ‏وَقَالَ ‏ ‏أَحْمَدُ ‏ ‏بِمَيَامِنِكُمْ ‏","","",""],[8299,8299,"","আমরা সবাই কথা বলেছি যে আমার বাবা কিভাবে তাকে ছুরি মেরেছে বলে যে, ঈশ্বর আপনাকে সেখানে যেতে দিয়েছেন, সে আগুনটা উদ্ধার করেছে, মানে আমি যুদ্ধ করতে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّمَا كَانَ طَعَامَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ وَاللَّهِ مَا كُنَّا نَرَى ‏ ‏سَمْرَاءَكُمْ ‏ ‏هَذِهِ وَلَا نَدْرِي مَا هِيَ وَإِنَّمَا كَانَ لِبَاسُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النِّمَارَ ‏ ‏يَعْنِي ‏ ‏بُرْدَ ‏ ‏الْأَعْرَابِ ‏","","",""],[8300,8300,"","আমরা আমার বাবার সাথে প্রত্নতত্ত্বের বাবার কথা বলেছিলাম... ...তার জন্য প্রার্থনা করলাম... ...আর সে তার জন্য প্রার্থনা করলো সপ্তম আর সপ্তম কমান্ডের প্রধানের কাছে. ছেলেরা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ زَعَمَ ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَوَّذُوا بِاللَّهِ مِنْ رَأْسِ السَّبْعِينَ وَإِمَارَةِ الصِّبْيَانِ ‏","","",""],[8301,8301,"","আমরা আমার ছেলেকে একজন জিনিয়াস হিসেবে নিয়ে কথা বলেছিলাম, ঈশ্বরের এটা করতে হবে আর সে তোমার আত্মা পরিপূর্ণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ ‏ ‏قَيْحًا ‏ ‏يَرِيهِ ‏ ‏خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[8302,8302,"","আমরা সবাই একটা দানবের কথা বলেছি, যে কিনা কথা বলছিল। তারা প্রভুর ইচ্ছার প্রতি শ্রদ্ধার কথা বলে এবং তাকে আত্মসমর্পণ করে তার কাছে, উষ্ণ এবং আলো ছিল এমন একজন মানুষ যিনি বলেছিলেন যে, সেই ব্যক্তির আত্মা হবে, যে কিনা হতে হবে সেই লোক। সে আমার প্রভুর প্রার্থনা ছেড়ে দিয়েছে এবং মানুষকে তার কাছে আশ্বস্ত করেছে যে সে যা চেয়েছে তা সে করেছে তুমি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏سُكَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَشَاهِدٌ ‏ ‏لِوَفْدِ عَبْدِ الْقَيْسِ ‏ ‏قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَنَهَاهُمْ أَنْ يَشْرَبُوا فِي هَذِهِ الْأَوْعِيَةِ ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏قَالَ فَقَامَ إِلَيْهِ رَجُلٌ مِنْ الْقَوْمِ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ النَّاسَ لَا ‏ ‏ظُرُوفَ ‏ ‏لَهُمْ قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّهُ ‏ ‏يَرْثِي ‏ ‏لِلنَّاسِ قَالَ فَقَالَ اشْرَبُوا مَا طَابَ لَكُمْ فَإِذَا ‏ ‏خَبُثَ ‏ ‏فَذَرُوهُ ‏","","",""],[8303,8303,"","আমরা তোমার জীবনের কথা বলছি... ...যার মানে আমার ভাই মুক্ত হওয়ার স্বপ্ন, সে যদি কখনো নেকড়েদের মাঝে আত্মসমর্পণ করে, তাহলে সে তাকে আত্মসমর্পণ করবে সে চলে গেলে আমাকে মেরে ফেলার জন্য সে একজন দেবতা হিসেবে পরিচিত মহাপুরুষের ছেলেকে ভালোবাসে।","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَفِي الْآخَرِ دَوَاءً ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَحَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[8304,8304,"","ঈশ্বর তা দূর করে দিয়েছেন এবং তিনি কখনোই উত্তম কথা বলেন না ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَاه ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مَا يَرَى أَنْ تَبْلُغَ حَيْثُ بَلَغَتْ يَهْوِي بِهَا فِي النَّارِ سَبْعِينَ خَرِيفًا ‏","","",""],[8305,8305,"","আমরা সবাই আমার বাবাকে যাজক হিসেবে নিয়ে কথা বলেছি, সে প্রথম বারের মত খুন করে, আর দ্বিতীয় বার তাকে খুন করে, সে অনেক কিছু বলেছে। প্রথমে বড় হবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏مَنْ قَتَلَ ‏ ‏الْوَزَغَ ‏ ‏فِي الضَّرْبَةِ الْأُولَى فَلَهُ كَذَا ‏ ‏وَكَذَا حَسَنَةً ‏ ‏وَمَنْ قَتَلَهُ فِي الثَّانِيَةِ فَلَهُ كَذَا وَكَذَا حَسَنَةً وَمَنْ قَتَلَهُ فِي الثَّالِثَةِ فَلَهُ كَذَا وَكَذَا ‏ ‏قَالَ ‏ ‏سُهَيْلٌ ‏ ‏الْأُولَى أَكْثَرُ ‏","","",""],[8306,8306,"","আমরা সবাই কথা বলেছি সে কিভাবে এমন কিছু বলেছে, ঈশ্বর তাকে আদেশ করেছেন আর আমি, বাবা, আমার প্রভু, আমাদের সবার সাথে কথা বলতে দিবেন না। আপনি বলেন, কোন শক্তি নেই। আপনি তো বলেন, আপনি তো আমাদের মধ্যে আছেন, আপনি কিছুই বলতে পারেন না। আপনি জানেন না। আপনি কি বলেন, আপনি কি বলেন? আপনি যদি আপনার বাবা, আপনি জানেন না, আপনি জানেন না, আপনি কি বলছেন, আপনি জানেন, আপনি জানেন না কি কি হয়েছে আপনার শক্তি আছে। আপনি কি? আপনি যদি আপনার কাছে কিছু আছে, আপনি জানেন না। আপনি জানেন না। আপনি জানেন না। আপনি জানেন, আপনি কি, আপনি জানেন না। আপনি জানেন না। আপনি কি, আপনি জানেন না? আপনি জানেন না। আপনি যদি আপনি জানেন না। আপনি জানেন না, আপনি জানেন না। ঈশ্বরের কাছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏حَدَّثَهُ قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كَنْزِ الْجَنَّةِ قَالَ قُلْتُ نَعَمْ فِدَاكَ أَبِي وَأُمِّي قَالَ تَقُولُ لَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[8307,8307,"","আমরা আমার বাবার ব্যাপারে কথা বলেছি কিন্তু ঈশ্বর আমার জন্য তার বাবার ঋণের কথা বলেছেন। ঈশ্বর তার কাছে প্রার্থনা করেছেন, আর তিনি তার প্রভুর কাছে প্রার্থনা করেছেন যেন তিনি তার প্রভুর কাছে আত্মসমর্পন করবেন। তিনি দুটি মাখন থাকে। তার পরাজয়ের জন্য, সে মারা যায়, আর তারপর সে বলে আমরা আপনার টাকা। তারা আমাদের ছেড়ে দেয় যা তারা গত ইরিসের দুর্দশা থেকে বের হয়ে আসে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ آتَاهُ اللَّهُ مَالًا فَلَمْ يُؤَدِّ زَكَاتَهُ مُثِّلَ لَهُ مَالُهُ يَوْمَ الْقِيَامَةِ ‏ ‏شُجَاعًا ‏ ‏أَقْرَعَ لَهُ ‏ ‏زَبِيبَتَانِ ‏ ‏يَأْخُذُ ‏ ‏بِلِهْزِمَتِهِ ‏ ‏يَوْمَ الْقِيَامَةِ ثُمَّ يَقُولُ أَنَا مَالُكَ أَنَا كَنْزُكَ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏لَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمْ اللَّهُ مِنْ فَضْلِهِ ‏} ‏إِلَى آخِرِ ‏ ‏الْآيَةَ ‏","","",""],[8308,8308,"","তিনি ঈশ্বরের কাছে তাঁর মনের সবচেয়ে ভাল আগ্রহ জানতে চেয়েছিলেন এবং বিগত দশ দিনে তিনি থেমে যাবেন । দুই বা দুই.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَكِفُ ‏ ‏فِي كُلِّ رَمَضَانَ عَشْرَةَ أَيَّامٍ فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ ‏ ‏اعْتَكَفَ ‏ ‏عِشْرِينَ يَوْمًا ‏","","",""],[8309,8309,"","আমরা একটা মাসোর কথা বলেছি, ঈশ্বরের পুত্রের প্রতি দয়া দেখানোর জন্য, আমার বাবা একজন পলাতক, ঈশ্বরের কাছে যে কিনা ঈশ্বরের কাছে বলেছে, সে আমার সবচেয়ে ভালো বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ الْمَدِينِيُّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلُّونَ بِكُمْ فَإِنْ أَصَابُوا فَلَكُمْ وَلَهُمْ وَإِنْ أَخْطَئُوا فَلَكُمْ وَعَلَيْهِمْ ‏","","",""],[8310,8310,"","আমরা আমার বাবার কথা বলেছিলাম তার ব্যাপারে... ...ঈশ্বর বলেছেন আমরা তার সাথে যা করেছি তা দিতে হবে... ...আর তুমি যা করেছ তা শেষ হয়ে গেছে.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَهَيْتُكُمْ عَنْهُ فَانْتَهُوا وَمَا أَمَرْتُكُمْ بِهِ فَخُذُوا مِنْهُ مَا اسْتَطَعْتُمْ ‏","","",""],[8311,8311,"","আমার বাবার সৎ বাবার কথা বলেছিলাম আমার বাবার একজন কুমারী হওয়া সম্পর্কে। ঈশ্বর তার কাছে প্রার্থনা করেন এবং তিনি দুটি অগ্নির স্তম্ভ দিয়েছেন, আমি তাদের আর দেখতে পাই না। তাদের বসরা তাদের মতোই। কল্পনার উন্নয়ন নরকের মতো হবে না এবং তার চেহারা খুঁজে বের করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِنْفَانِ مِنْ أَهْلِ النَّارِ لَا ‏ ‏أَرَاهُمَا بَعْدُ نِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ ‏ ‏مَائِلَاتٌ ‏ ‏مُمِيلَاتٌ ‏ ‏عَلَى رُءُوسِهِنَّ مِثْلُ ‏ ‏أَسْنِمَةِ ‏ ‏الْبُخْتِ ‏ ‏الْمَائِلَةِ لَا يَرَيْنَ الْجَنَّةَ وَلَا يَجِدْنَ رِيحَهَا وَرِجَالٌ مَعَهُمْ أَسْوَاطٌ كَأَذْنَابِ الْبَقَرِ يَضْرِبُونَ بِهَا النَّاسَ ‏","","",""],[8312,8312,"","আমি আমার বাবার সঙ্গে এক ঘনিষ্ঠ সম্পর্ক গড়ে তুলতে চেয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِجِدَارٍ ‏ ‏أَوْ حَائِطٍ ‏ ‏مَائِلٍ فَأَسْرَعَ الْمَشْيَ فَقِيلَ لَهُ فَقَالَ إِنِّي أَكْرَهُ مَوْتَ ‏ ‏الْفَوَاتِ ‏","","",""],[8313,8313,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং যে - বিষয়টা আমি তোমাকে মেঘের মৃত্যু নিয়ে যাব, সেটা উৎসর্গ করেছেন, নাকি মারা যাচ্ছে? মৃত্যু অথবা আমি মস্তিষ্কের জন্য মরব.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَمُوتَ غَمًّا أَوْ هَمًّا أَوْ أَنْ أَمُوتَ غَرَقًا أَوْ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ أَوْ أَنْ أَمُوتَ ‏ ‏لَدِيغًا ‏","","",""],[8314,8314,"","আমরা ঈশ্বরের মহিমা নিয়ে কথা বলেছি যখন আমরা আমার পিতার প্রেমে মাসের জন্য যুদ্ধ করতে সাহায্য করব, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং স্বর্গ ও করুণার প্রতি শ্রদ্ধা প্রকাশ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ مِنْ السُّمِّ ‏ ‏وَالْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[8315,8315,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন আমি তাকে জিজ্ঞেস করি, ‘ কেন? ’","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِي الْحَلْبَسِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمَحْرُومُ مَنْ حُرِمَ غَنِيمَةَ كَلْبٍ ‏","","",""],[8316,8316,"","বাবার ভালবাসার স্বপ্ন নিয়ে আমার বাবার সাথে কথা বলেছি, ঈশ্বরের সব দোষ তাঁর কাছে আর গরুদের পাঠিয়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَوَّارَاتِ الْقُبُورِ ‏","","",""],[8317,8317,"","আমরা বাবার স্বপ্নের কথা বলেছিলাম... ...একজন জিনিয়াসের প্রতি বাবার ভালোবাসা নিয়ে... ...আর ঈশ্বরের কাছে প্রার্থনা করবে... ...যদি আমি তাকে বিক্রি করে দেই...","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَرَقَ عَبْدُ أَحَدِكُمْ فَلْيَبِعْهُ وَلَوْ ‏ ‏بِنَشٍّ ‏","","",""],[8318,8318,"","বাবার ভালবাসার স্বপ্ন নিয়ে বাবার সাথে কথা বলেছিলাম। ঈশ্বর তার কাছে প্রার্থনা করেন এবং আমি প্রভুর কাছে প্রার্থনা করি, আর তোমার ইচ্ছা পরিবর্তন করে তার সাথে মিল রেখে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْفُوا اللِّحَى وَخُذُوا الشَّوَارِبَ وَغَيِّرُوا شَيْبَكُمْ وَلَا تَشَبَّهُوا ‏ ‏بِالْيَهُودِ ‏ ‏وَالنَّصَارَى ‏","","",""],[8319,8319,"","আমরা আমার বাবার সঙ্গে ঘোড়ার পিঠে চড়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَمُحَمَّدُ بْنُ سَابِقٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ بِأَنْفُسِهِمْ مَنْ تَرَكَ مَالًا فَلِمَوَالِي ‏ ‏عَصَبَتِهِ ‏ ‏وَمَنْ تَرَكَ ‏ ‏ضِيَاعًا ‏ ‏أَوْ ‏ ‏كَلًّا ‏ ‏فَأَنَا وَلِيُّهُ فَلَا دَاعِيَ لَهُ ‏","","",""],[8320,8320,"","আর আমি এই বন্ধনটা করতে চাই, ঈশ্বর এটা করেছেন, আর যদি তিনি আত্মসমর্পণ করেন তাহলে তিনি আত্মসমর্পণ করবেন। এবং তিনি তা করতে ব্যর্থ হবেন না যদি তিনি এই কাজ করেন। এবং তিনি কখনও করেছেন কি না।","‏ ‏و قَالَ ‏ ‏أَسْوَدُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَفْسُقْ وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[8321,8321,"","আমরা বাবার ভালবাসার স্বপ্ন নিয়ে কথা বলেছিলাম। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাদের সবার কাছে প্রার্থনা করেছেন, যারা গর্ভ ও গর্ভনিরোধক ফিরে এসেছে তাদের সবার জন্য। গর্ভের মধ্যে, ঘুমটা অমর।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ كُلُّهُمْ حَقٌّ عَلَى كُلِّ مُسْلِمٍ ‏ ‏عِيَادَةُ ‏ ‏الْمَرِيضِ وَشُهُودُ الْجِنَازَةِ ‏ ‏وَتَشْمِيتُ ‏ ‏الْعَاطِسِ إِذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8322,8322,"","একবারের জন্য আমার ছেলের হাত আছে। বাবার সর্বোচ্চ বলায়, আমার বাবার কাছে পবিত্র হওয়া উচিত।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَرْدِ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏الْمَازِنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالْخَيْلَ ‏ ‏الْمُنَفِّلَةَ ‏ ‏فَإِنَّهَا إِنْ تَلْقَ تَفِرَّ وَإِنْ تَغْنَمْ ‏ ‏تَغُلَّ ‏","","",""],[8323,8323,"","আমি আমার বাবাকে একজন উৎপীড়ক হিসেবে বর্ণনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اكْتَحَلَ أَحَدُكُمْ فَلْيَكْتَحِلْ ‏ ‏وِتْرًا ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيَسْتَجْمِرْ ‏ ‏وِتْرًا ‏","","",""],[8324,8324,"","আমরা আমার বাবার সাথে আমার ছেলের সাথে যুদ্ধ করছি, তার একজন মাস্টারের শান্তি থাকবে, আর তাকে আমার মাথা গুটিয়ে রাখতে হবে. তারা আপনাকে ঈশ্বরের কাছে প্রার্থনা করে বলে যে, তিনি তার জন্য প্রার্থনা করেছেন এবং আমাকে বলছেন যে, এটা আমার।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ أَعْرَابِيًّا غَزَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏فَأَصَابَهُ مِنْ ‏ ‏سَهْمِهَا ‏ ‏دِينَارَانِ فَأَخَذَهُمَا الْأَعْرَابِيُّ فَجَعَلَهُمَا فِي عَبَاءَتِهِ وَخَيَّطَ عَلَيْهِمَا وَلَفَّ عَلَيْهِمَا فَمَاتَ الْأَعْرَابِيُّ فَوَجَدُوا الدِّينَارَيْنِ فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَيَّتَانِ ‏","","",""],[8325,8325,"","ঈশ্বর আমাদের প্রভু এবং তিনি গরু ও পঞ্চম পঞ্চম মস্তকের জন্য যোগ্য হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّكْبِيرُ فِي الْعِيدَيْنِ سَبْعًا قَبْلَ الْقِرَاءَةِ وَخَمْسًا بَعْدَ الْقِرَاءَةِ ‏","","",""],[8326,8326,"","আমার বাবা আমার ছেলেকে যে নির্যাতন করে, সে বলে যে অপরাধীর বিরুদ্ধে তার নাম রাখা হয়েছে এবং তাদের নেতারা হয়তো ঈশ্বরের দুই ছেলের কথা বলেছে । এখানে ফিরে আসা ভাল বিশ্বাস আছে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَهْلُ الْجَنَّةِ ‏ ‏رَشْحُهُمْ ‏ ‏الْمِسْكُ وَوُقُودُهُمْ ‏ ‏الْأَلُوَّةُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ لَهِيعَةَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا ‏ ‏الْأَلُوَّةُ ‏ ‏قَالَ ‏ ‏الْعُودُ الْهِنْدِيُّ الْجَيِّدُ ‏","","",""],[8327,8327,"","আমরা একটা ছেলের কথা বলেছিলাম যে এক ছেলের চেয়ে বেশি বিভ্রান্ত হয়ে পড়েছিল, যে কিনা একবার ঈশ্বরের কাছে আমার সবচেয়ে ভাল কিছু করতে হবে। আমি ঈশ্বরের কাছে প্রার্থনা করছি, ঈশ্বর তার কাছে প্রার্থনা করুন। আমি আশা করি, ঈশ্বর যেন তাঁর কাছে প্রার্থনা করেন। আমি আমার প্রার্থনা করি, আমি যেন তাঁর কাছে প্রার্থনা করি। আমি আমার প্রার্থনা করি, আমি যেন তাঁর কাছে প্রার্থনা করি। এবং আমি আমার বাবা-মা-মা-মা-কে বলি, আমি যেন আমি আমার প্রার্থনা করি, আমার বাবা-মা-র কাছে ক্ষমা প্রার্থনা করি। আর কি না করি? সে অন্ধকারের মেয়েদের হত্যা করবে, সে বিষ সারাবে","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ يَزِيدَ الْعَطَّارَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَذَاكَرُوا ‏ ‏الْكَمَأَةَ ‏ ‏فَقَالُوا هِيَ ‏ ‏جُدَرِيُّ الْأَرْضِ وَمَا نَرَى أَكْلَهَا يَصْلُحُ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الْكَمَأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ مِنْ السُّمِّ ‏","","",""],[8328,8328,"","আমি ঈশ্বরের কাছে প্রার্থনা করি, তিনি আমার বাবার নাম পড়েছেন, উত্তেজনাটা চরম নয়। হাতিতে, পরের সাতটি চোখে একই রকম।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَقَرَأَ عَلَيْهِ ‏ ‏أُبَيٌّ ‏ ‏أُمَّ الْقُرْآنِ ‏ ‏فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ مَا أُنْزِلَ فِي التَّوْرَاةِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ وَلَا فِي الْفُرْقَانِ مِثْلُهَا إِنَّهَا ‏ ‏السَّبْعُ الْمَثَانِي ‏ ‏وَالْقُرْآنُ الْعَظِيمُ ‏ ‏الَّذِي أُعْطِيتُ ‏","","",""],[8329,8329,"","আমরা কথা বলেছি যে আমার বাবা কিভাবে উড়তে পারেন। ঈশ্বর তাঁর ছেলের জন্য ঈশ্বরের প্রতি ভালবাসা দেখিয়েছেন, আর তিনি তার ছেলের জন্য ঈশ্বরের কাছে ফিরে যাবেন এবং পরবর্তী দুই জনের কাছে ফিরে যাবেন। আমি বললাম, দ্বিতীয়টি, আমার ছেলে এবং আমি আমার প্রভুর দিন চুরি করেছি। আমি বলেছি তিন আর আমি জিতে গেছি ঈশ্বরের প্রভু আর ঈশ্বর বলে আমি ঘুমিয়েছি আর আমি টাকা দিতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُصُّ عَلَى الْمِنْبَرِ ‏ { ‏وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ ‏} ‏فَقُلْتُ وَإِنْ زَنَى وَإِنْ سَرَقَ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثَّانِيَةَ ‏ { ‏وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ ‏} ‏فَقُلْتُ الثَّانِيَةَ وَإِنْ زَنَى وَإِنْ سَرَقَ يَا رَسُولَ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثَّالِثَةَ ‏ { ‏وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ ‏} ‏فَقُلْتُ الثَّالِثَةَ وَإِنْ زَنَى وَإِنْ سَرَقَ يَا رَسُولَ اللَّهِ فَقَالَ نَعَمْ وَإِنْ رَغِمَ أَنْفُ ‏ ‏أَبِي الدَّرْدَاءِ ‏","","",""],[8330,8330,"","আমরা দুটো উপায় চেষ্টা করেছি বলে যে বাবা আমার বাবার চেয়ে তোমার টাকা ভালো। লর্ড তার জন্য প্রার্থনা করেছে এবং যদি তিনি মুক্তির মূল্য দেন তাহলে তাকে উদ্ধার করা হবে। জীবনের প্রাণ, শয়তান.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سُهَيْلٍ نَافِعُ بْنُ مَالِكِ بْنِ أَبِي عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ وَغُلِّقَتْ أَبْوَابُ النَّارِ ‏ ‏وَصُفِّدَتْ ‏ ‏الشَّيَاطِينُ ‏","","",""],[8331,8331,"","আমরা বাবার সাথে কথা বলেছি যে সে তার জীবনের জন্য তোমার টাকা করবে। আমি তার জন্য প্রার্থনা করছি এবং সে বলেছে যে তিন পক্ষের একটি ঘটনা। মিথ্যার মতো ঘটেছে আর পরে ভুল জায়গায় যাওয়ার পরে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سُهَيْلٍ نَافِعُ بْنُ مَالِكِ بْنِ أَبِي عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏آيَةُ الْمُنَافِقِ ثَلَاثٌ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا اؤْتُمِنَ خَانَ ‏","","",""],[8332,8332,"","আমরা বাবার সাথে আমার ভালবাসার কারণে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি যা করেছেন তাতে কিছু যায় না বলে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عُمْرَى ‏ ‏فَمَنْ ‏ ‏أُعْمِرَ ‏ ‏شَيْئًا فَهُوَ لَهُ ‏","","",""],[8333,8333,"","আমরা স্যামের সাথে কথা বলেছি. আমাকে বলতে বলুন আমি ঈশ্বর সম্পর্কে ক্লান্ত. আমি আমার বাবাকে বলতে চাই যে, ঈশ্বরের ক্ষমতা আছে যা আমি করতে চাই এবং জিজ্ঞেস করতে চাই যে আমি কার কাছে যাচ্ছি. লবণ পানিতে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عَبْدِ اللَّهِ الْقَرَّاظَ ‏ ‏يَصِيحُ فِي الْمَسْجِدِ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَرَادَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏بِسُوءٍ أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[8334,8334,"","আমার গডফাদার স্বপ্নের কথা বলেছিলাম আর তার জন্য প্রার্থনা করেছে, আর তারা যা করেছে সব সবই তার জন্য, প্রত্যেকটা টিচারকে ফিরিয়ে দেয়া হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ كُلُّهُنَّ حَقٌّ عَلَى كُلِّ مُسْلِمٍ ‏ ‏عِيَادَةُ ‏ ‏الْمَرِيضِ وَاتِّبَاعُ الْجَنَائِزِ ‏ ‏وَتَشْمِيتُ ‏ ‏الْعَاطِسِ إِذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8335,8335,"","আমি আমার বাবার সাথে কথা বলেছিলাম আমার বাবা জিনিয়াস হওয়ার কথা।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَمَنَّى أَحَدُكُمْ فَلْيَنْظُرْ مَا يَتَمَنَّى فَإِنَّهُ لَا يَدْرِي مَا يُكْتَبُ لَهُ مِنْ أُمْنِيَّتِهِ ‏","","",""],[8336,8336,"","আমরা আমার বাবাকে বাঁচাতে চেষ্টার কথা বলেছিলাম, ঈশ্বরের দোহাই, ঈশ্বরের কাছে প্রার্থনা করব আর বধিরদের কাছে, লর্ড লর্ডের কাছে, ঈশ্বরের কাছে, ঈশ্বরের প্রভুর কাছে, ঈশ্বরের কাছে, ভাল থেকে ভালোর জন্য ভাল.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَاعَدَهُ اللَّهُ مِنْ جَهَنَّمَ سَبْعِينَ خَرِيفًا ‏","","",""],[8337,8337,"","আমরা বিখ্যাত চাঁদ দ্বারা আমাদের বাপ্তিস্ম চুরি করার চেষ্টা করেছি, ঈশ্বরের দয়া পেয়েছে, প্রার্থনা করেছি ঈশ্বরের কাছে এটা শান্তি এনেছে. খোদা, আমরা তো ফিরে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمَّارٍ ‏ ‏مُؤَذِّنُ ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدًا الْمَقْبُرِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خَيْرَ الْكَسْبِ كَسْبُ يَدَيْ عَامِلٍ إِذَا نَصَحَ ‏","","",""],[8338,8338,"","আমরা সময় চুরি করার চেষ্টা করেছি কিন্তু আমাকে সাহায্য করুন, আমার বাবা এমন এক উপহার যে তাকে ঈশ্বর তাকে যে জিতেছে এবং আমি তা করেছি। তার শত্রু, সে আমাকে দিয়ে দিয়েছে আর তারপর সে মুক্ত হয়ে গেল, তারপর সে গাছের নিচে পড়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏إِسْمَاعِيلَ بْنَ أُمَيَّةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏ثَلَاثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ وَمَنْ كُنْتُ خَصْمَهُ خَصَمْتُهُ رَجُلٌ أَعْطَى بِي ثُمَّ غَدَرَ وَرَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ وَرَجُلٌ اسْتَأْجَرَ أَجِيرًا فَاسْتَوْفَى مِنْهُ وَلَمْ يُوَفِّهِ أَجْرَهُ ‏","","",""],[8339,8339,"","আমি বাবার সাথে কথা বলেছি যে সে না নিবে কিনা, আমি দুঃখিত, অথবা জীবাশ্ম।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏عَنْ السَّبْقِ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبُو صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏سَبْقَ ‏ ‏إِلَّا فِي ‏ ‏خُفٍّ ‏ ‏أَوْ ‏ ‏حَافِرٍ ‏","","",""],[8340,8340,"","আমরা একটা ছেলের চেয়ে ভালো কথা বলেছি যে আমাকে বিভ্রান্ত করেছে, ঈশ্বর আদেশ দিয়েছেন আর তিনি আত্মসমর্পণ করবেন যদি তিনি দাবি করেন যে আপনি আপনার ঋণের কথা বলেছেন আর তোমার নিরাপত্তা আর তোমার চাচার সাথে বিশ্বাসঘাতকতা।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا وَدَّعَ أَحَدًا قَالَ ‏ ‏أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ ‏","","",""],[8341,8341,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম, কিন্তু ঈশ্বর একবার আমাকে নিয়ে এসেছেন, বাবা বলেছে সে তার কাছে প্রার্থনা করেছে আর সে আমাকে বলে সে আমাকে এটা আলো দিতে বলেছে, সে গ্যারেজে আছে, তারপর সে পরিষ্কার হয়ে গেছে। তারপর সে সেটা বিপথে নিয়ে গেল, তারপর সে তা উপেক্ষা করে, আর তারা পরিষ্কার হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ عَبْدِ اللَّهِ الْبَجَلِيَّ ‏ ‏حَدَّثَنِي ‏ ‏مَوْلًى لِأَبِي هُرَيْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضِّئْنِي فَأَتَيْتُهُ بِوَضُوءٍ ‏ ‏فَاسْتَنْجَى ‏ ‏ثُمَّ أَدْخَلَ يَدَهُ فِي التُّرَابِ فَمَسَحَهَا ثُمَّ غَسَلَهَا ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقُلْتُ يَا رَسُولَ اللَّهِ رِجْلَاكَ لَمْ تَغْسِلْهُمَا قَالَ إِنِّي أَدْخَلْتُهُمَا وَهُمَا طَاهِرَتَانِ ‏","","",""],[8342,8342,"","ঈশ্বরের দোহাই আমরা আমার বাবার ছেলের কথা বলেছি মানে হচ্ছে একটা গাল বিজয়ীর নাম... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বললেন আমি তোমার মাথা উড়িয়ে দিব, না হলে তুমি তোমার কাজ করবে না আর আমি তোমার গরুকে মেরে ফেলব না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ يَعْنِي ابْنَ زَائِدَةَ بْنِ نَشِيطٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏تَفَرَّغْ لِعِبَادَتِي أَمْلَأْ صَدْرَكَ غِنًى وَأَسُدَّ فَقْرَكَ وَإِلَّا تَفْعَلْ مَلَأْتُ صَدْرَكَ شُغْلًا وَلَمْ أَسُدَّ فَقْرَكَ ‏","","",""],[8343,8343,"","আমরা আমার বাবা একজন দেবতা হওয়ার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَامِلٌ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَذْهَبُ الدُّنْيَا حَتَّى تَصِيرَ ‏ ‏لِلُكَعِ ‏ ‏ابْنِ ‏ ‏لُكَعٍ ‏","","",""],[8344,8344,"","আমরা আমার বাবা একজন পলাতক ছিলেন, যে বলেছিল সে এটা বলতে যাচ্ছে, তাকে আত্মসমর্পণ করতে হবে। তার মানে অনেক মানুষ এই কথা বলেছে এবং এটাই বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْمُكْثِرِينَ ‏ ‏يَعْنِي هُمْ الْأَقَلُّونَ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا ‏","","",""],[8345,8345,"","আমরা দুজন বাপ্তিস্মের কথা বলেছি, যা আমরা বাবার ছেলের সাথে কথা বলেছি, সে এর সাথে যেতে চেষ্টা করছে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি বললেন, প্রাচীনরা জীবন আর জীবনের দুটো প্রেম করবে। রাজার মৃত্যু.","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ طُولِ الْحَيَاةِ وَكَثْرَةِ الْمَالِ ‏","","",""],[8346,8346,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি বলবেন যে, কেন ঈশ্বর তাঁর বইতে লিখে দিয়েছেন । তার ক্ষমতা আছে নিজের ভুল করার।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابٍ فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي ‏","","",""],[8347,8347,"","আমি ঈশ্বরের কাছে প্রার্থনা করব যেন তিনি চান এটা তার জন্য এবং একটি পাথরের মতো হতে পারেন. ...মন্ত্রের কালো পোশাকের মত...","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ صَبِيحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏الْمَنِيحَةُ ‏ ‏تَغْدُو ‏ ‏بِأَجْرٍ ‏ ‏وَتَرُوحُ ‏ ‏بِأَجْرٍ ‏ ‏وَمَنِيحَةُ ‏ ‏النَّاقَةِ كَعِتَاقَةِ الْأَحْمَرِ ‏ ‏وَمَنِيحَةُ ‏ ‏الشَّاةِ كَعِتَاقَةِ الْأَسْوَدِ ‏","","",""],[8348,8348,"","আমরা দুটো যুক্তি নিয়ে কথা বলেছি, আমার বাবার বেড়ে ওঠায় সাহায্য করার ব্যাপারে। ঈশ্বরের উত্তর হচ্ছে, আমি কাকে হত্যা করতে চাই এবং তুমি কে?","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ ‏ ‏جُهْدُ ‏ ‏الْمُقِلِّ ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[8349,8349,"","আমরা আমার বাবার এত ভাল কথা বলেছি যে আমরা একজন পর্যটককে একটা কুড়ালের ছেলে বানাতে চেয়েছিলাম। যে কোন কিছু।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ ‏ ‏السَّنَةُ ‏ ‏بِأَنْ لَا تُمْطَرُوا وَلَكِنَّ ‏ ‏السَّنَةَ ‏ ‏أَنْ تُمْطَرُوا ثُمَّ تُمْطَرُوا فَلَا تُنْبِتُ الْأَرْضُ شَيْئًا ‏","","",""],[8350,8350,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার চিন্তার চেয়ে বরং আপনার আনুগত্য অর্জন করেছেন । যাও বসে বসে কিছু কাজ করো। তারা বলে যে, তোমার শপথ থেকে তোমাকে মেরে ফেলবে। যদি তারা তাকে দেখে এবং যদি তারা তাদের আত্মার সাথে অভ্যস্ত হয় তবে তারা তোমাকে মেরে ফেলবে। তারা তাকে দেখে, হয়তো আমি চলে গিয়েছিলাম। তাদের বলতে হবে, ঈশ্বর তাদের জন্য দায়ী, যারা তাদের বংশধরদের সাথে নেই, যারা তাদের জন্য ভালোবাসা পোষণ করে। বাবার বাবা দেবী হিসেবে আপনার আনুগত্যের জন্য সমবেদনা জানিয়েছেন, স্যার, প্রভুর আধুনিককে স্পর্শ না করে বরং,","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلَّهِ عَزَّ وَجَلَّ مَلَائِكَةً ‏ ‏فُضُلًا ‏ ‏يَتَّبِعُونَ مَجَالِسَ الذِّكْرِ يَجْتَمِعُونَ عِنْدَ الذِّكْرِ فَإِذَا مَرُّوا بِمَجْلِسٍ عَلَا بَعْضُهُمْ عَلَى بَعْضٍ حَتَّى يَبْلُغُوا الْعَرْشَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُمْ وَهُوَ أَعْلَمُ مِنْ أَيْنَ جِئْتُمْ فَيَقُولُونَ مِنْ عِنْدِ عَبِيدٍ لَكَ يَسْأَلُونَكَ الْجَنَّةَ ‏ ‏وَيَتَعَوَّذُونَ بِكَ مِنْ النَّارِ وَيَسْتَغْفِرُونَكَ فَيَقُولُ يَسْأَلُونِي جَنَّتِي هَلْ رَأَوْهَا فَكَيْفَ لَوْ رَأَوْهَا وَيَتَعَوَّذُونَ مِنْ نَارِ جَهَنَّمَ فَكَيْفَ لَوْ رَأَوْهَا فَإِنِّي قَدْ غَفَرْتُ لَهُمْ فَيَقُولُونَ رَبَّنَا إِنَّ فِيهِمْ عَبْدَكَ الْخَطَّاءَ فُلَانًا مَرَّ بِهِمْ لِحَاجَةٍ لَهُ فَجَلَسَ إِلَيْهِمْ فَقَالَ اللَّهُ عَزَّ وَجَلَّ أُولَئِكَ الْجُلَسَاءُ لَا يَشْقَى بِهِمْ جَلِيسُهُمْ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ لِلَّهِ عَزَّ وَجَلَّ مَلَائِكَةً ‏ ‏سَيَّارَةً ‏ ‏فُضُلًا ‏ ‏يَلْتَمِسُونَ مَجَالِسَ الذِّكْرِ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[8351,8351,"","আমরা আমার বাবার এত ভাল হওয়ার কথা বলেছিলাম যে আমরা একটা বদমাশের জন্য ভাল কাজ করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করেছেন, যদি সে তার সফর থেকে তার পা দেখতে পায় দেখতে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُرَى عَضَلَةُ سَاقِهِ مِنْ تَحْتِ ‏ ‏إِزَارِهِ ‏ ‏إِذَا ‏ ‏اتَّزَرَ ‏","","",""],[8352,8352,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বলেছিলেন যে, ঈশ্বর যেন আশীর্বাদ করেন এবং আমার কাছে ফিরে আসেন । কল্পনা করতে হবে, তার আত্মা নিয়ে, সেই রাতের জন্য আমি আমার হাজার হাজার লোকের সাথে লড়বো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ سَأَلْتُ رَبِّي عَزَّ وَجَلَّ ‏ ‏فَوَعَدَنِي أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا عَلَى صُورَةِ الْقَمَرِ لَيْلَةِ الْبَدْرِ فَاسْتَزَدْتُ فَزَادَنِي مَعَ كُلِّ أَلْفٍ سَبْعِينَ أَلْفًا فَقُلْتُ أَيْ رَبِّ إِنْ لَمْ يَكُنْ هَؤُلَاءِ مُهَاجِرِي أُمَّتِي قَالَ إِذَنْ أُكْمِلَهُمْ لَكَ مِنْ ‏ ‏الْأَعْرَابِ ‏","","",""],[8353,8353,"","আমরা দুজন সালমামোনের সাথে কথা বলেছি যার মানে হল, আমরা সিঁড়ির মাঝে বন্ধুত্ব করেছি। আমার বাবাকে বেছে নেওয়া হয়েছিল ঈশ্বর ও তার প্রভুর দেবী হতে, আর আমি আর কখনোই তা করতে পারবো না। বলে দিন, আমি রাতে বৃষ্টি চুরি করতে আর আগুনের আগুনে তাদের আওয়াজ তুলতে বলেছি। তাকে এটা বলতে হবে যে, ঈশ্বরের প্রতি বিশ্বাস মহান ঈশ্বরের শাসন থেকে লাভ করেছে এবং বলে দিয়েছে। আমি বিশ্বাস করি যে, ঈশ্বর আমাদের প্রার্থনা শোনেন ।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ يَعْنِي الطَّيَالِسِيَّ ‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ بْنُ مُوسَى السُّلَمِيُّ الدَّقِيقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ وَاسِعٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏لَوْ أَنَّ عِبَادِي أَطَاعُونِي لَأَسْقَيْتُهُمْ الْمَطَرَ بِاللَّيْلِ وَأَطْلَعْتُ عَلَيْهِمْ الشَّمْسَ بِالنَّهَارِ وَلَمَا أَسْمَعْتُهُمْ صَوْتَ الرَّعْدِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ حُسْنَ الظَّنِّ بِاللَّهِ عَزَّ وَجَلَّ مِنْ حُسْنِ عِبَادَةِ اللَّهِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَدِّدُوا إِيمَانَكُمْ قِيلَ يَا رَسُولَ اللَّهِ وَكَيْفَ نُجَدِّدُ إِيمَانَنَا قَالَ أَكْثِرُوا مِنْ قَوْلِ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[8354,8354,"","আমরা আমার ছেলের ব্যাপারে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে বলতে চাই যে আমি কাকে কষ্ট পেয়েছি বা তার ছায়াতে ফেলে দিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَنْظَرَ ‏ ‏مُعْسِرًا أَوْ ‏ ‏وَضَعَ ‏ ‏لَهُ أَظَلَّهُ اللَّهُ فِي ظِلِّ عَرْشِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[8355,8355,"","বিয়ে করার ব্যাপারে আমার বাবা একজন সাহসী ব্যক্তি। মুখ বন্ধ করে ঈশ্বর জিতে গেছেন এবং আমি বিরক্ত হয়ে গেছি","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏قُرَّةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ كَلَامٍ ‏ ‏أَوْ أَمْرٍ ‏ ‏ذِي بَالٍ لَا يُفْتَحُ بِذِكْرِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ ‏ ‏أَبْتَرُ ‏ ‏أَوْ قَالَ أَقْطَعُ ‏","","",""],[8356,8356,"","আমি আমার বাবার জন্য দুঃখিত, একজন পলাতক বলেছিলেন, আমি তার জন্য প্রার্থনা করছি এবং সে যদি তোমাকে কল করে, তাহলে তুমি আমার কাছে বলবে, মা তোমাকে ফোন করবে আপনার প্রভু এবং তার পালনকর ্ তা, আমরা বলেছি আপনি অনেক মারা যান কিন্তু বলা হয় হত্যা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْمَدَائِنِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَبِيبٍ الْأَزْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَبِيبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏شُبَيْلِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِثَوْبَانَ ‏ ‏كَيْفَ أَنْتَ يَا ‏ ‏ثَوْبَانُ ‏ ‏إِذْ تَدَاعَتْ عَلَيْكُمْ الْأُمَمُ كَتَدَاعِيكُمْ عَلَى ‏ ‏قَصْعَةِ ‏ ‏الطَّعَامِ يُصِيبُونَ مِنْهُ قَالَ ‏ ‏ثَوْبَانُ ‏ ‏بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ أَمِنْ قِلَّةٍ بِنَا قَالَ لَا أَنْتُمْ يَوْمَئِذٍ كَثِيرٌ وَلَكِنْ يُلْقَى فِي قُلُوبِكُمْ الْوَهَنُ قَالُوا وَمَا الْوَهَنُ يَا رَسُولَ اللَّهِ قَالَ حُبُّكُمْ الدُّنْيَا وَكَرَاهِيَتُكُمْ الْقِتَالَ ‏","","",""],[8357,8357,"","ঈশ্বর এবং তিনি নিজেকে আত্মসমর্পণ করেছেন, যে - ব্যক্তি এই হুমকিগুলোকে চুম্বন করছে এবং বন্ধুত্বকে গ্রহণ না করে বরং গ্রহণ করছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْبَلُ الْهَدِيَّةَ وَلَا يَقْبَلُ ‏ ‏الصَّدَقَةَ ‏","","",""],[8358,8358,"","আমরা দুটো রহস্যের বিষয়ে আরও ভাল জীবন সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَتْ الْكَبَائِرُ ‏","","",""],[8359,8359,"","তার নীরবতা তৈরি করা হয়েছিল এবং তাকে দুপুরের খাবারের বিরতির সময় ধরা হয়েছিল । তার বাবা-মা তার নিজের মৃত্যুর জন্য দায়ী.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَبِيبٍ الْأَزْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَبِيبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏شُبَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَائِمًا يَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏فَقَالَ لِأَصْحَابِهِ ‏ ‏مَنْ كَانَ أَصْبَحَ مِنْكُمْ صَائِمًا فَلْيُتِمَّ صَوْمَهُ وَمَنْ كَانَ أَصَابَ مِنْ غَدَاءِ أَهْلِهِ فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ ‏","","",""],[8360,8360,"","আমার বাবা আমার সাথে কথা বলার চেষ্টা করেছেন, সে হয়ত এমন লোকদের ছেড়ে দেবে যারা লর্ডের হাতে দাঁড়িয়ে আছে, ডুবে ডুবে ডুবে ডুবে তাকে নরকে ডুবিয়ে মেরে ফেলা হয়েছিল আর এই সময় অসভ্যদের অসভ্যরা বিষে আক্রান্ত হয়ে মারা যায়। আর আমি দুঃখিত, ধন্যবাদ, আমি তার দিকে তাকিয়ে আছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏شُبَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُنَاسٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏قَدْ صَامُوا يَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏فَقَالَ مَا هَذَا مِنْ الصَّوْمِ قَالُوا هَذَا الْيَوْمُ الَّذِي نَجَّى اللَّهُ ‏ ‏مُوسَى ‏ ‏وَبَنِي إِسْرَائِيلَ ‏ ‏مِنْ الْغَرَقِ وَغَرَّقَ فِيهِ ‏ ‏فِرْعَوْنَ ‏ ‏وَهَذَا يَوْمُ ‏ ‏اسْتَوَتْ ‏ ‏فِيهِ السَّفِينَةُ عَلَى ‏ ‏الْجُودِيِّ ‏ ‏فَصَامَهُ ‏ ‏نُوحٌ ‏ ‏وَمُوسَى ‏ ‏شُكْرًا لِلَّهِ تَعَالَى فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَحَقُّ ‏ ‏بِمُوسَى ‏ ‏وَأَحَقُّ بِصَوْمِ هَذَا الْيَوْمِ فَأَمَرَ أَصْحَابَهُ بِالصَّوْمِ ‏","","",""],[8361,8361,"","আমরা আমার বাবাকে বলেছিলাম যে কিভাবে তাকে ভালবাসতে হয়। ঈশ্বর তার কাছে প্রার্থনা করলেন আর তিনি বলেছিলেন যে ঈশ্বর আমার আশীর্বাদে আরো তিনগুণ বেশী। তোমরা জানো তোমরা, তোমরা কি? ঈশ্বর আপনাকে বধির ও বধির লোকেদের আদেশ দিয়েছেন, এমন কিছু পান করা ও শোনা হয় ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ رَضِيَ لَكُمْ ثَلَاثًا وَكَرِهَ لَكُمْ ثَلَاثًا رَضِيَ لَكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَأَنْ تَنْصَحُوا لِمَنْ وَلَّاهُ اللَّهُ أَمْرَكُمْ وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا وَكَرِهَ لَكُمْ قِيلَ وَقَالَ وَكَثْرَةَ السُّؤَالِ وَإِضَاعَةَ الْمَالِ ‏","","",""],[8362,8362,"","আমরা আমার নাম নিয়ে কথা বলেছি, ঈশ্বর তার ইচ্ছার কথা জিজ্ঞেস করেছেন, আর যে তাকে ছেড়ে চলে যেতে বলেছিল সে নাকি ঈশ্বরের কাছে না... ...কিন্তু তোমার ক্রেতার ব্যথা আছে। তার ভালোর কথা দাও, সে আমাকে তোমার মতো স্পর্শ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ مَنْ قَالَهَا عَشْرَ مَرَّاتٍ حِينَ يُصْبِحُ كُتِبَ لَهُ بِهَا مِائَةُ حَسَنَةٍ وَمُحِيَ عَنْهُ بِهَا مِائَةُ سَيِّئَةٍ وَكَانَتْ لَهُ ‏ ‏عَدْلَ ‏ ‏رَقَبَةٍ وَحُفِظَ بِهَا يَوْمَئِذٍ حَتَّى يُمْسِيَ وَمَنْ قَالَ مِثْلَ ذَلِكَ حِينَ يُمْسِي كَانَ لَهُ مِثْلُ ذَلِكَ ‏","","",""],[8363,8363,"","আমরা নাবিকের পক্ষে একটা লাইন জিততে চেয়েছিলাম, আমরা ঈশ্বরের বার্তাবাহকের সাথেও গিয়েছিলাম, যদি আমরা ২ বছর ধরে আত্মসমর্পণ করতাম। দ্বিতীয়টা হল দ্বিতীয়টা। ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন, যেন তিনি আমার বাবার কাছে আত্মসমর্পণ করেন, দেখতেই পারছেন, তিনি আসলে কে ছিলেন, তিনি বলেছিলেন তিনি একজন পরাজিত। তিনি প্রার্থনা করেছিলেন তিনি এটা করেছেন এবং তিনি আমাদের ঈশ্বরের দিন আমাদের দেবেন।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ هَاشِمٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ كِنَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا تَحْتَ ‏ ‏ثَنِيَّةِ لِفْتٍ ‏ ‏طَلَعَ عَلَيْنَا ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏انْظُرْ مَنْ هَذَا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ عَبْدُ اللَّهِ هَذَا ‏","","",""],[8364,8364,"","আমরা ঈশ্বরের কথা বলেছি কিন্তু বেনের প্রতি ভালো বিশ্বাস আছে বলে খুশি। আমার বাবা একটা উপহার যে নবী তাকে ছেড়ে দিয়েছেন... ...যে আমার ভবিষ্যদ্বাণীর দ্বারা তাকে ছেড়ে দিয়েছে যে কাপুরুষ হওয়া উচিত।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَجِيدِ بْنِ سُهَيْلِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْبَرِي هَذَا عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ ‏","","",""],[8365,8365,"","আমি কিভাবে বৃদ্ধ হয়ে সাহায্য করতে চেষ্টা করছি, আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন তার কাছে প্রার্থনা করেছেন এবং তিনি বেঁচে থাকবেন না এবং সম্পাদনা করা হবে না. আপনি স্বপ্ন দেখছেন কিছু প্রভু হতে পারে. আপনি স্বপ্ন দেখছেন যে আপনি জানেন আমি কি না আপনি জানেন আমি কি করছি আপনি যদি আমি আমার বাবা আমাকে সাহায্য করতে চান এবং আপনি একটি উপহার দিতে চান. আমি একটি উপহার পেতে চাই. আপনি কি না যে আপনি কি করে আপনি কি না? আমি আপনার বাবা, আপনি কি করে জানেন আপনি কি করতে পারেন? আপনি কি না? আপনি যদি আপনি আমার বাবা আমাকে সাহায্য করতে চান? আপনি জানেন, আপনি একটি উপহার দিতে চান, আপনি কি না? আপনি একটি উপহার আছে? আপনি কি না? আপনি একটি উপহার আছে? আপনি একটি মহান পিতা? আপনি কি? আপনি কি? আপনি কি? আপনি আপনার বাবা? আপনি কি জানেন না? আপনি আপনার বাবা, আপনি কি একটি মহান পিতা? আপনি কি? আপনি কি? আপনি একটি মহান শিক্ষক? দাস কিন্তু লর্ড নয়, সে এটা নিতে পারে না যে তার রক্ত নিয়ে স্বপ্ন আছে। এখানে আমরা তার বুকের জন্য সই করি, সে খারাপ লোকের হাত থেকে তাকে ঘৃণা করতে পারে ভাই।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ كُرَيْزٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَحْقِرُهُ وَلَا يَخْذُلُهُ كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏فِي حَدِيثِهِ وَمَالُهُ وَعِرْضُهُ ‏ ‏التَّقْوَى هَاهُنَا التَّقْوَى هَاهُنَا يُشِيرُ إِلَى صَدْرِهِ ثَلَاثًا حَسْبُ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ ‏","","",""],[8366,8366,"","আমরা তাদের কথা বলেছি আমার আশীর্বাদকে ধরতে সাহায্য করার চেষ্টা করে। তিনি বললেন, \"ঈশ্বর, তুমি আমাদের ডাকছেন যে আমি আসলে বলছি না\"।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ إِنَّكَ تُدَاعِبُنَا قَالَ ‏ ‏إِنِّي لَا أَقُولُ إِلَّا حَقًّا ‏","","",""],[8367,8367,"","আমার বাবার স্বপ্ন ছিল একটা কুত্তার ছেলের চেয়ে ভালো হওয়া। আমার বাবা একজন পলাতক মানুষ। আমি দেখলাম, আমার টাকা দিয়ে কি হবে। গুলি করো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنِ ‏ ‏ابْنِ مُطَرِّفٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ عُدِيَ عَلَى مَالِي قَالَ ‏ ‏فَانْشُدْ ‏ ‏اللَّهَ فَإِنْ أَبَوْا فَقَاتِلْ فَإِنْ قُتِلْتَ فَفِي الْجَنَّةِ وَإِنْ قَتَلْتَ فَفِي النَّارِ ‏","","",""],[8368,8368,"","আমরা দু'বার কথা বলেছি, কিন্তু আমার ক্ষমা আছে, তার কাছে একটা ভবিষ্যদ্বাণীর ব্যাপারে... ...আর সে বলবে আমি যদি তোমাকে সেট করি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيُوتِرْ ‏","","",""],[8369,8369,"","আর যদি কুকুরকে বলা হয় আমি তোমাকে কোথায় চ্যালেঞ্জ করবো, সে একবার এটা ধুয়ে ফেলবে।","‏ ‏وَإِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[8370,8370,"","আর এর থেকে ভালো পানিকে থামাতে পারেনি।","‏ ‏وَلَا يَمْنَعْ ‏ ‏فَضْلَ ‏ ‏مَاءٍ لِيَمْنَعَ بِهِ ‏ ‏الْكَلَأَ ‏","","",""],[8371,8371,"","আর পানি পাওয়ার জন্য চেষ্টা করা, সে আবার ফিরে আসবে।","‏ ‏وَمِنْ حَقِّ الْإِبِلِ أَنْ تُحْلَبَ عَلَى الْمَاءِ يَوْمَ ‏ ‏وِرْدِهَا ‏","","",""],[8372,8372,"","আমরা তোমাকে সাহায্য করার চেষ্টা করার সময় কিছু কথা বলেছিলাম। সে বলল সে কেন তোমাকে খুন করবে আর সে তোমাকে খুন করবে, আমি কখনো তা করবো না। আমি যা করব তা হবে খারাপ, আমি তোমার জীবন থেকে বেঁচে থাকার জন্য বেঁচে আছি, আমার ছেলে মারা গেছে, আমি তোমার প্রাণ রক্ষা করছি, আমি নিশ্চিত তুমি ক্লান্ত, আমি এটা তার জন্য করব। সময় আমরা কথা বলেছি আমরা কিভাবে এটা করেছি. আমার বাবা একজন পলাতক... ...সে কেন বলেছে সে ঈশ্বরের কাছে প্রার্থনা করেছে আর তাকে যেতে বলেছে, আমি আশা করি তোমার কোন ক্ষতি নেই, আর আমরা কাজ করি না।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشًا ‏ ‏فَعَمَّ وَخَصَّ فَقَالَ يَا مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا مَعْشَرَ ‏ ‏بَنِي كَعْبِ بْنِ لُؤَيٍّ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا مَعْشَرَ ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا مَعْشَرَ ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏أَنْقِذِي نَفْسَكِ مِنْ النَّارِ فَإِنِّي وَاللَّهِ مَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا إِلَّا أَنَّ لَكُمْ رَحِمًا ‏ ‏سَأَبُلُّهَا ‏ ‏بِبِلَالِهَا ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَإِنِّي لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ ضَرًّا وَلَا نَفْعًا ‏ ‏يَعْنِي ‏ ‏فَاطِمَةَ ‏ ‏عَلَيْهَا السَّلَام ‏","","",""],[8373,8373,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমার সমস্ত মাকে স্বর্গে সমর্পণ করবেন । ছড়ি আমার বাবাকে হারাতে পারে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ أُمَّتِي يَدْخُلُ الْجَنَّةَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ أَبَى قَالُوا وَمَنْ ‏ ‏يَأْبَى يَا رَسُولَ اللَّهِ قَالَ مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ وَمَنْ عَصَانِي فَقَدْ أَبَى ‏","","",""],[8374,8374,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং গুয়েসকে তার আসন ছেড়ে দিবেন, যখন আমি সবচেয়ে বিখ্যাত ছিলাম ঈশ্বরের দোহাই তাকে এটা করতে বাধ্য করেছে আর সে এটা নিয়ে কথা বলেছে আর কিছু ক্ষমতা বলেছে সে বলেছিল যে সে ঘন্টা ধরে প্রশ্ন করতে পারে বিকেলে, অথবা সে আমাকে কি বলে যদি অর্ডারটা এক ঘন্টাও না দেয়া হয়...","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ يُحَدِّثُ الْقَوْمَ فِي مَجْلِسِهِ حَدِيثًا جَاءَ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ فَمَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ فَقَالَ بَعْضُ الْقَوْمِ سَمِعَ فَكَرِهَ مَا قَالَ وَقَالَ بَعْضُهُمْ بَلْ لَمْ يَسْمَعْ حَتَّى إِذَا قَضَى حَدِيثَهُ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ هَا أَنَا ذَا يَا رَسُولَ اللَّهِ قَالَ إِذَا ضُيِّعَتْ الْأَمَانَةُ فَانْتَظِرْ السَّاعَةَ قَالَ يَا رَسُولَ اللَّهِ كَيْفَ ‏ ‏أَوْ قَالَ مَا ‏ ‏إِضَاعَتُهَا قَالَ ‏ ‏إِذَا ‏ ‏تَوَسَّدَ ‏ ‏الْأَمْرَ غَيْرُ أَهْلِهِ فَانْتَظِرْ السَّاعَةَ ‏","","",""],[8375,8375,"","আমি যদি তা করতাম, তা হলে আমি লোকেদের সঙ্গে খেলাধুলা করতাম, তাই করতাম । যা খুশি তাই নিয়েছো, ঈশ্বর জিতেও গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَجُلًا لَمْ يَعْمَلْ خَيْرًا قَطُّ فَكَانَ يُدَايِنُ النَّاسَ فَيَقُولُ لِرَسُولِهِ خُذْ مَا تَيَسَّرَ وَاتْرُكْ مَا عَسُرَ وَتَجَاوَزْ لَعَلَّ اللَّهَ يَتَجَاوَزُ عَنَّا فَلَمَّا هَلَكَ قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ هَلْ عَمِلْتَ خَيْرًا قَطُّ قَالَ لَا إِلَّا أَنَّهُ كَانَ لِي غُلَامٌ وَكُنْتُ أُدَايِنُ النَّاسَ فَإِذَا بَعَثْتُهُ ‏ ‏يَتَقَاضَى قُلْتُ لَهُ خُذْ مَا تَيَسَّرَ وَاتْرُكْ مَا عَسُرَ وَتَجَاوَزْ لَعَلَّ اللَّهَ عَزَّ وَجَلَّ يَتَجَاوَزُ عَنَّا قَالَ اللَّهُ عَزَّ وَجَلَّ قَدْ تَجَاوَزْتُ عَنْكَ ‏","","",""],[8376,8376,"","আমরা বেন জেনেন থেকে শ্বাস নিই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ الدَّارَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِنَّ الْمُؤْمِنَ عِنْدِي بِمَنْزِلَةِ كُلِّ خَيْرٍ يَحْمَدُنِي وَأَنَا أَنْزِعُ نَفْسَهُ مِنْ بَيْنِ جَنْبَيْهِ ‏","","",""],[8377,8377,"","আমার ছেলে যখন আমাকে দেখে, তখন আমরা বাবা - মায়ের সঙ্গে আমার প্রতি ঈর্ষা করে একটা বাচ্চাকে নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏السَّاعِي عَلَى الْأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ أَوْ كَالَّذِي يَقُومُ اللَّيْلَ وَيَصُومُ النَّهَارَ ‏","","",""],[8378,8378,"","বাবা আমার বোকা বাবার ব্যাপারে দ্বিতীয় ছেলের সাথে জয়ের স্বপ্নের কথা বলেছিলাম, ঈশ্বর দাবি করেছেন, যারা টাকা নিয়ে টাকা নিয়ে গেছে। মানুষের সমবেদনা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ أَمْوَالَ النَّاسِ يُرِيدُ أَدَاءَهَا أَدَّاهَا اللَّهُ عَنْهُ وَمَنْ أَخَذَهَا يُرِيدُ إِتْلَافَهَا أَتْلَفَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[8379,8379,"","আমি আমার ভাইকে আমার বাবার সম্বন্ধে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى ‏ ‏غَيْرَهَا ‏ ‏خَيْرًا مِنْهَا فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَفْعَلْ الَّذِي هُوَ خَيْرٌ ‏","","",""],[8380,8380,"","বাবা একটা ছেলেকে জিততে সাহায্য করার স্বপ্ন নিয়ে কথা বলেছিলেন। বাবার ঈর্ষা ঠাণ্ডা আর তিনি তার বাবার কথা শুনবেন। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন আমরা মুক্ত হব। মুক্তভাবে বলা হয়েছিল যে, প্রভু তার জন্য প্রার্থনা করেন এবং তিনি তার নিজের আশার রান্না করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏مِنْ آلِ ‏ ‏ابْنِ الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏وَهُوَ مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ ‏ ‏رَجُلٌ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏","","",""],[8381,8381,"","আমরা ঈশ্বরের পুত্র, আমাদের সাথে কথা বলার সময় একজন ভালো বন্ধুর দ্বারা বাপ্তাইজিত হয়েছি। মানুষ তোমাদের সেরা, তাদের গণনায় ঐ দুই টাকা দিয়ে...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَذْهَبَ عَنْكُمْ ‏ ‏عُبِّيَّةَ ‏ ‏الْجَاهِلِيَّةِ وَفَخْرَهَا بِالْآبَاءِ مُؤْمِنٌ تَقِيٌّ وَفَاجِرٌ شَقِيٌّ وَالنَّاسُ بَنُو ‏ ‏آدَمَ ‏ ‏وَآدَمُ ‏ ‏مِنْ تُرَابٍ لَيَنْتَهِيَنَّ أَقْوَامٌ فَخْرَهُمْ بِرِجَالٍ أَوْ لَيَكُونُنَّ أَهْوَنَ عَلَى اللَّهِ مِنْ عِدَّتِهِمْ مِنْ ‏ ‏الْجِعْلَانِ ‏ ‏الَّتِي تَدْفَعُ بِأَنْفِهَا النَّتَنَ ‏","","",""],[8382,8382,"","আমার বাবা একজন পলাতকের কথা বলেছিলাম যে ঈশ্বরের কাছে প্রার্থনা করেছে যে তিনি ঈশ্বরের কাছে নিজেকে উৎসর্গ করেছেন, আমরা শপথ করছি যে এটা সত্য এবং শোনা ও শোনা সম্ভব। অপরাধ অথবা অপরাধ সংঘটিত হওয়ার কথা ছিল, যা সূর্যের আওয়াজে শোনা যেত ।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا وَأَدَّى زَكَاةَ مَالِهِ طَيِّبًا بِهَا نَفْسُهُ ‏ ‏مُحْتَسِبًا ‏ ‏وَسَمِعَ وَأَطَاعَ فَلَهُ الْجَنَّةُ ‏ ‏أَوْ دَخَلَ الْجَنَّةَ ‏ ‏وَخَمْسٌ لَيْسَ لَهُنَّ كَفَّارَةٌ الشِّرْكُ بِاللَّهِ عَزَّ وَجَلَّ وَقَتْلُ النَّفْسِ بِغَيْرِ حَقٍّ أَوْ نَهْبُ مُؤْمِنٍ أَوْ الْفِرَارُ يَوْمَ الزَّحْفِ أَوْ يَمِينٌ ‏ ‏صَابِرَةٌ ‏ ‏يَقْتَطِعُ بِهَا مَالًا بِغَيْرِ حَقٍّ ‏","","",""],[8383,8383,"","আমরা একটি ছেলে আমার ভালবাসা অর্জন করেছে এমন এক প্রতিবেশীর সাথে কথা বলেছি। ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করা হয়েছে এবং আরো একবার সেবা করার জন্য তা আরো একবার প্রদান করা হবে। - হ্যাঁ।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَدٌّ ‏ ‏يُقَامُ فِي الْأَرْضِ خَيْرٌ لِلنَّاسِ مِنْ أَنْ يُمْطَرُوا ثَلَاثِينَ أَوْ أَرْبَعِينَ صَبَاحًا ‏","","",""],[8384,8384,"","আমরা হারোণের সাথে কথা বলেছি যে আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছি। ঈশ্বর হয়ত তাকে আদেশ দিয়েছেন আর আমাকে এটা করতে বলেছেন। আমি দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ هُوَ ابْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَوْا إِلَى مَا قَالَ رَبُّكُمْ عَزَّ وَجَلَّ قَالَ ‏ ‏مَا أَنْعَمْتُ عَلَى عِبَادِي مِنْ نِعْمَةٍ إِلَّا أَصْبَحَ فَرِيقٌ مِنْهُمْ بِهَا كَافِرِينَ يَقُولُونَ الْكَوْكَبُ وَبِالْكَوْكَبِ ‏","","",""],[8385,8385,"","আমরা এমন একজনের সাথে কথা বলেছি যার নাম হয়তো ঈশ্বরের নামও হয়তো পরাজিত ছেলে বলে কথা বলেছে। ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তাকে অন্ধকার পানিতে পাওয়া যায়নি এবং তারপর হতে হবে। তাকে দূরে সরিয়ে রাখো।","‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ قَدْ سَمَّاهُ وَهُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏","","",""],[8386,8386,"","তিনি বলেছিলেন আমরা কয়েক বছর আগে কথা বলেছি, আমরা ভালো বাবার জন্য জিতে যাবো, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বলবে আপনি নাকি তার শ্রদ্ধার গেরিলা। প্রবৃত্তি করতে হয়","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّكُمْ ‏ ‏الْغُرُّ ‏ ‏الْمُحَجَّلُونَ ‏ ‏يَوْمَ الْقِيَامَةِ مِنْ آثَارِ الطُّهُورِ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏","","",""],[8387,8387,"","আমরা আমাদের বাবার সুন্দর উলকির কথা বলেছিলাম যখন আমরা একটা শিকারীর কথা বলেছিলাম। আমরা বলতে চাই, প্রভু তার কাছে প্রার্থনা করেছেন। আর শান্তি ফিরে আসবে। মনে হয় আমরা প্রার্থনা করবো যেন তোমরা জয়ের জন্য তোমার জন্য ভাল সময় পাবে। আমি কি সবচেয়ে ছোট হতে পারি যে তুমি ভালো কাজ করছ এবং তারপর ভালো হবে তোমার কাজ। সিঁড়ি বলবে, প্রভু, তুমি সিঁড়ির মত, আর আমি তোমার ভয় পাওয়ার একমাত্র উপায়, সে শেষ পর্যন্ত তার ইচ্ছা মেনে নিতে পারবে না, সে হয়তো ভালো মানুষ হতে পারে, কিন্তু সবচেয়ে ভালোটা। আমার বাবার কাছ থেকে বিয়ারের শব্দ শুনি নাই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِذْ ذَاكَ وَنَحْنُ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجِيءُ الْأَعْمَالُ يَوْمَ الْقِيَامَةِ فَتَجِيءُ الصَّلَاةُ فَتَقُولُ يَا رَبِّ أَنَا الصَّلَاةُ فَيَقُولُ إِنَّكِ عَلَى خَيْرٍ فَتَجِيءُ الصَّدَقَةُ فَتَقُولُ يَا رَبِّ أَنَا الصَّدَقَةُ فَيَقُولُ إِنَّكِ عَلَى خَيْرٍ ثُمَّ يَجِيءُ الصِّيَامُ فَيَقُولُ أَيْ يَا رَبِّ أَنَا الصِّيَامُ فَيَقُولُ إِنَّكَ عَلَى خَيْرٍ ثُمَّ تَجِيءُ الْأَعْمَالُ عَلَى ذَلِكَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ إِنَّكَ عَلَى خَيْرٍ ثُمَّ يَجِيءُ الْإِسْلَامُ فَيَقُولُ يَا رَبِّ أَنْتَ السَّلَامُ وَأَنَا الْإِسْلَامُ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ إِنَّكَ عَلَى خَيْرٍ بِكَ الْيَوْمَ آخُذُ وَبِكَ أُعْطِي فَقَالَ اللَّهُ عَزَّ وَجَلَّ فِي كِتَابِهِ ‏ { ‏وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنْ الْخَاسِرِينَ ‏} ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏ثِقَةٌ وَلَكِنَّ ‏ ‏الْحَسَنَ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[8388,8388,"","আমরা সবচেয়ে ভালোদের সাথে কথা বলেছি। আমার বাবা একজন কুমারী। সবকিছু শুরু কর, আর মাথা খারাপ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ بْنِ زَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏مَوْلَى ‏ ‏يَزِيدَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏إِنْ تُعْطِ الْفَضْلَ فَهُوَ خَيْرٌ لَكَ وَإِنْ تُمْسِكْهُ فَهُوَ شَرٌّ لَكَ وَابْدَأْ بِمَنْ تَعُولُ وَلَا يَلُومُ اللَّهُ عَلَى الْكَفَافِ وَالْيَدُ الْعُلْيَا خَيْرٌ لَكَ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[8389,8389,"","আর সে আমার বাবাকে ফোন করেছে, একটা ঘোড়া... ...যে বলেছে যে ভবিষ্যদ্বাণী তাকে এমন একজনকে উদ্ধার করতে বলেছে যে আমাকে খুন করতে বলেছে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ ‏ ‏مُرْنِي بِأَمْرٍ وَلَا تُكْثِرْ عَلَيَّ حَتَّى أَعْقِلَهُ قَالَ لَا تَغْضَبْ فَأَعَادَ عَلَيْهِ فَأَعَادَ عَلَيْهِ قَالَ لَا تَغْضَبْ ‏","","",""],[8390,8390,"","আমরা আমার বাবা, আমার ভাই, আগুন, আমার বাবার দুই ঘোড়া নিয়ে কথা বলেছি। আল্লাহ তাঁর পতাকা দাবি করেছেন এবং ঈশ্বরের করুণায় আত্মসমর্পন করেছেন। খাও।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏حُرِّمَتْ عَلَيْهِمْ الشُّحُومُ فَبَاعُوهَا وَأَكَلُوا أَثْمَانَهَا ‏","","",""],[8391,8391,"","আমরা আমার ভাই মারসাইর মুক্তির ব্যাপারে আমার বাবা মারাইর কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مِرَايَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُصَلِّي الْمَلَائِكَةُ عَلَى ‏ ‏نَائِحَةٍ ‏ ‏وَلَا عَلَى ‏ ‏مُرِنَّةٍ ‏","","",""],[8392,8392,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি যেগুলো সে আমাকে সাহায্য করার চেষ্টা করছে। আমার বাবা ভবিষ্যদ্বাণীর উপহার যিনি তাকে আদেশ দিয়েছেন এবং একটা অপরাধের দালানে পৌঁছে দেয়া হবে। পাপের কন্যা।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ وَهُوَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ زِيَادٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بِنَاءُ الْجَنَّةِ ‏ ‏لَبِنَةٌ ‏ ‏مِنْ ذَهَبٍ ‏ ‏وَلَبِنَةٌ ‏ ‏مِنْ فِضَّةٍ ‏","","",""],[8393,8393,"","আমরা বাবার সাহায্য নিয়ে কথা বলেছি, আমার বাবাকে একটা দেবী খুঁজতে সাহায্য করার জন্য ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তাকে আত্মসমর্পণ করতে বলেছে আমি ফোন করতে কিছুই জানি না।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ شَيْءٌ أَكْرَمَ عَلَى اللَّهِ مِنْ الدُّعَاءِ ‏","","",""],[8394,8394,"","আমি শুনেছি গুহাতে কতবার আমরা পার্থক্য করেছি, আমি তার জন্য প্রার্থনা করেছি এবং সে আমার বিল্ডিং এ ছিল বলে আমি তাকে বলতে চাই, কিন্তু আমি খুশি হব। আনন্দের সাথে শ্বাস নেওয়াটা আনন্দের ছিল এবং আমরা যেতে যেতে এবং যেতে চেয়েছিলাম। আমার প্রভু আমার বাবার বয়স অনুযায়ী কথা বলেছিলেন। আমি ভেবেছিলাম, আমি এখন আর কখনো ভুলব না। আমি আর কখনো ভুলব না। আমি আর আমার বাবা-মা আমাদের সাথে নেই। আমি এখন আর আমার বাবা আমাদের পরিবারের একজন সদস্য। আমি এখন আর আমি এখন আর আমার বাবা। আমি এখন এই বিষয়ে কথা বলব না। আমি জানি না। আমি জানি না যে, আমি এখন আমি জানি, আমি আমার বাবা আমাদের বাবা। আমি এখন অনেক খুশি। আমি এখন আমি এখন আমি এই সিদ্ধান্ত নিয়েছি। আমি জানি যে, আমি এখন আমি এই বিষয়টি নিয়ে কথা বলছি। আমি এখন আমি জানি। আমি জানি যে, আমি জানি, আমি কি করবো?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ضَمْضَمُ بْنُ جَوْسٍ الْهِفَّانِيُّ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَانَ فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏رَجُلَانِ أَحَدُهُمَا مُجْتَهِدٌ فِي الْعِبَادَةِ وَالْآخَرُ مُسْرِفٌ عَلَى نَفْسِهِ وَكَانَا مُتَآخِيَيْنِ فَكَانَ الْمُجْتَهِدُ لَا يَزَالُ يَرَى عَلَى الْآخَرِ ذَنْبًا فَيَقُولُ ‏ ‏وَيْحَكَ ‏ ‏أَقْصِرْ فَيَقُولُ الْمُذْنِبُ ‏ ‏خَلِّنِي ‏ ‏وَرَبِّي فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏أَبِي عَامِرٍ ‏","","",""],[8395,8395,"","আমি আমার ভাই হার্বারের কথা বলেছিলাম সে আমাকে কি বলেছে, সে হাল ছেড়ে দিত যদি তার কাছে একজন ইহুদির জীবন থাকে, যারা আমার উপর বিশ্বাস করত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ آمَنَ عَشَرَةٌ مِنْ ‏ ‏أَحْبَارِ ‏ ‏الْيَهُودِ ‏ ‏آمَنُوا بِي كُلُّهُمْ ‏","","",""],[8396,8396,"","শিকার সম্পর্কে আমরা কথা বলেছিলাম, বাবা আমাকে হত্যা করতে বলেছিল। আমি বাবাকে হারপারকে জিজ্ঞেস করবো... ...যে তার জন্য প্রার্থনা করে... তাকে বেছে নাও আর তুমি তাকে ভালভাবেই করবে, যাও তার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْجُلَاسِ عُقْبَةُ بْنُ سَيَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ شَمَّاخٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏مَرْوَانَ ‏ ‏سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الْجِنَازَةِ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏اللَّهُمَّ أَنْتَ رَبُّهَا وَأَنْتَ خَلَقْتَهَا وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ وَأَنْتَ قَبَضْتَ رُوحَهَا وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا جِئْنَا شُفَعَاءَ فَاغْفِرْ لَهَا ‏","","",""],[8397,8397,"","আমার যখন আমার ভালবাসা ছিল, তখন আমার বাবা বধিরদের কথা বলেছিলেন। আমার বাবা একজন সাহসী যে ঈশ্বরের কাছে প্রার্থনা করেছিল এবং সে বেড়া থেকে নিজেকে সরিয়ে নিতে এবং ভুল পথে চলে যেতে চেয়েছিল। তাছাড়া খাবার আর পানীয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَطْفِئُوا ‏ ‏السُّرُجَ ‏ ‏وَأَغْلِقُوا الْأَبْوَابَ ‏ ‏وَخَمِّرُوا ‏ ‏الطَّعَامَ وَالشَّرَابَ ‏","","",""],[8398,8398,"","আমরা আমার বাবার কথা বলেছি একটি ভাস্কর্যের মূর্তি নিয়ে শোনার ব্যাপারে। তিনি আমাকে বলেছেন, আল্লাহ তাঁর কাছে প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كَنْزِ الْجَنَّةِ مِنْ تَحْتِ الْعَرْشِ لَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[8399,8399,"","কিন্তু বৃষ্টি হওয়ার জন্য বছর নয় কিন্তু বছরে বিষ ছড়িয়ে পড়ে আর ভাববাদীর কাছে নয়","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏السَّنَةُ ‏ ‏أَنْ لَا يَكُونَ مَطَرٌ وَلَكِنَّ ‏ ‏السَّنَةَ ‏ ‏أَنْ تُمْطِرَ السَّمَاءُ وَلَا تُنْبِتُ الْأَرْضُ ‏","","",""],[8400,8400,"","আমরা এমন এক ছেলের কাছ থেকে রক্ষা পাওয়ার চেষ্টা করেছি, যিনি বন্দী নন। ঈশ্বর মুক্তি দিয়েছেন এবং বলেছেন, মানুষ তিন বছর ধরে আবেগ এবং আবেগে জর্জরিত, তারা কখনই তাদের জীবন পাবে না। তারা তাদের কষ্ট ভোগ করেছে বলে মনে হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُحْشَرُ النَّاسُ ثَلَاثَةَ أَصْنَافٍ صِنْفًا مُشَاةً وَصِنْفًا رُكْبَانًا وَصِنْفًا عَلَى وُجُوهِهِمْ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَمْشُونَ عَلَى وُجُوهِهِمْ فَقَالَ إِنَّ الَّذِي أَمْشَاهُمْ عَلَى أَقْدَامِهِمْ قَادِرٌ عَلَى أَنْ يُمْشِيَهُمْ عَلَى وُجُوهِهِمْ أَمَا إِنَّهُ ‏ ‏يَتَّقُونَ ‏ ‏بِكُلِّ ‏ ‏حَدَبٍ ‏ ‏وَشَوْكٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏يَتَّقُونَ بِوُجُوهِهِمْ كُلَّ ‏ ‏حَدَبٍ ‏ ‏وَشَوْكٍ ‏","","",""]];
